(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/poems-0031.js"] = [{"id":"poem-cabb1efe017c1b962946657c","title":"送从翁中丞奉使黠戛斯六首 四","author":"赵嘏","dynasty":"唐","verses":["牢山望断绝尘氛，滟滟河西拂地云。","谁见鲁儒持汉节，玉关降尽可汗军。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-1ce6e84a-ef90-4870-aad3-b11948c19d92","tags":[]},{"id":"poem-cabcc9631228a1128c0fdaf8","title":"送白宾客分司东都","author":"张籍","dynasty":"唐","verses":["赫赫声名三十春，高情人独出埃尘。","病辞省闼归闲地，恩许宫曹作上宾。","诗里难同相得伴，酒边多见自由身。","老人也拟休官去，便是君家池上人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-12d6d253-6aa8-43ea-98ae-6fbd0bafbbf7","tags":[]},{"id":"poem-cac72abfda173c57baf0bc8a","title":"醉桃源・阮郎归·菖蒲叶老水平沙","author":"周邦彦","dynasty":"宋","verses":["菖蒲叶老水平沙。","临流苏小家。","画阑曲径宛秋蛇。","金英垂露华。","烧蜜炬，引莲娃。","酒香薰脸霞。","再来重约日西斜。","倚门听暮鸦。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-418","tags":[]},{"id":"poem-cad1c97f06cc1d5717e93f2b","title":"和周赞善闻子规","author":"张籍","dynasty":"唐","verses":["秦城啼楚鸟，远思更纷纷。","况是街西夜，偏当雨里闻。","应投最高树，似隔数重云。","此处谁能听，遥知独有君。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-c6662459-18b5-4cef-9f1b-e52a3b185b18","tags":[]},{"id":"poem-cad40f00c501b1328d419cf5","title":"颂古七十六首  其一","author":"释士珪","dynasty":"宋","verses":["老胡不免出胞胎，也解人前恁么来。","指地指天称第一，众生四十九年灾。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-7d463a1e-094e-4744-a48a-2762ee46ec45","tags":[]},{"id":"poem-cad8fb344804d268225350d6","title":"水调歌头·琼树挂初日","author":"王之道","dynasty":"宋","verses":["琼树挂初日，珠箔卷清霜。","夜来溪上微雨，佳节过重阳。","共庆当年此际，曾见天麟协梦，华阀挂蓬桑。","人作鲁侯祝，俾尔寿而臧。","保疲瘵，旌德善，致吉祥。","会看报政，朝夕芝检趣征黄。","不藉灵丹九转，不用蟠桃三窃，源远自流长。","愿借沧溟富，斟酌荐瑶觞。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-140","tags":[]},{"id":"poem-cae7e721da3f6db5a337cb7c","title":"新亭","author":"张栻","dynasty":"宋","verses":["风景自今古，斯亭今是非。","绝怜江水去，还有故山围。","得失同千虑，成亏共一机。","所思惟谢傅，不但胜淮淝。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-834e79dc-cd27-4a38-a5a3-dbc46ebeb9a1","tags":[]},{"id":"poem-caeb86ca64a3d2e4f95ccb5d","title":"颂古十九首  其七","author":"释法全","dynasty":"宋","verses":["日暖风和莺啭新，柳垂金线系东君。","东君不惜无私力，一点花红一点春。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-493c3f20-a25d-441d-88cc-016d4445ec17","tags":[]},{"id":"poem-caf32e59a5a385b726e34dc4","title":"看花回·屈指劳生百岁期","author":"柳永","dynasty":"宋","verses":["屈指劳生百岁期。","荣瘁相随。","利牵名惹逡巡过，奈两轮、玉走金飞。","红颜成白发，极品何为。","尘事常多雅会稀。","忍不开眉。","画堂歌管深深处，难忘酒盏花枝。","醉乡风景好，携手同归。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-75","tags":[]},{"id":"poem-caf7e9ce0d2db0531375a24d","title":"思匡山贾匡","author":"贯休","dynasty":"唐","verses":["山兄诗癖甚，寒夜更何为。","觅句唯顽坐，严霜打不知。","石膏黏木屐，崖蜜落冰池。","近见禅僧说，生涯胜往时。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-49c329a1-eceb-4993-a1d2-9d6497af346f","tags":["庐山"]},{"id":"poem-cafebc91135dad8ebd86cd33","title":"春晴","author":"王驾","dynasty":"宋","verses":["雨前初见花间蕊，雨后全无叶底花。","蜂蝶纷纷过墙去，却疑春色在邻家。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-春晴","tags":[]},{"id":"poem-cb0c7fa65bd854dadf4610db","title":"采莲令·月华收","author":"柳永","dynasty":"宋","verses":["月华收，云淡霜天曙。","西征客、此时情苦。","翠娥执手送临歧，轧轧开朱户。","千娇面、盈盈伫立，无言有泪，断肠争忍回顾。","一叶兰舟，便恁急桨凌波去。","贪行色、岂知离绪。","万般方寸，但饮恨，脉脉同谁语。","更回首、重城不见，寒江天外，隐隐两三烟树。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-143","tags":["宋词三百首"]},{"id":"poem-cb0fd4212114b2f5b4c06c64","title":"早春泛镜湖","author":"宋之问","dynasty":"唐","verses":["漾舟喜湖广，湖广趣非一。","愉目野载芜，清心山更出。","孤烟昼藏火，薄暮朝开日。","但爱春光迟，不觉舟行疾。","归雁空间尽，流莺花际失。","远情自此多，景霁风物和。","芦人收晚钓，棹女弄春歌。","野外寒事少，湖间芳意多。","杂花因烂熳，暄柳日逶迤。","为客顿逢此，于思柰若何？","（此诗见《永乐大典》卷二二六七「六模」「湖」字「镜湖」条。","〖二函二十册〗）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-e96ca118-ac7e-4998-8a4f-675549667ec1","tags":[]},{"id":"poem-cb12c86eef3ef32b92b3d721","title":"送湖南提刑安学士  其一","author":"华镇","dynasty":"宋","verses":["洞庭六月暑风长，使者征帆挂短樯。","汲引津途多肉食，追随行路有壶浆。","南洲自恋涵濡德，北阙方思献纳良。","更识高门延庆事，彩衣新有桂枝香。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-57ed5d8c-0769-4b2a-bcc2-e1a3eac952b1","tags":["洞庭湖"]},{"id":"poem-cb1740cbbe822ae9b563f142","title":"西江月·悟了莫求寂灭","author":"张伯端","dynasty":"宋","verses":["悟了莫求寂灭，随缘只接群迷。","寻常邪见及提携。","方便指归实际。","五眼三身四智，六度万行修齐。","圆光一颗好摩尼。","利物兼能自利。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-991","tags":[]},{"id":"poem-cb2263f30ae3d9fa013d83e8","title":"悲长安","author":"子兰","dynasty":"唐","verses":["何事天时祸未回，生灵愁悴苦寒灰。","岂知万倾繁华地，强半今为瓦砾堆。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-91d45b28-57c9-469e-8e93-ddc41b21638f","tags":[]},{"id":"poem-cb28452461869ec937f94793","title":"题江湖伟观","author":"范晞文","dynasty":"宋","verses":["西湖何处可消愁，快上人间百尺楼。","千里山川浮王气，百年形势壮皇州。","逋仙宅近梅应古，坡老祠空竹自秋。","立徧阑干无限意，六桥歌舞懒回头。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-d612d43c-e224-469a-9b9f-ca1c818caef8","tags":["西湖"]},{"id":"poem-cb2b6b6464b37f8f4b24a28a","title":"送赵给事姪尉丹阳","author":"李端","dynasty":"唐","verses":["太傅怜群从，门人亦贱回。","入官先爱子，赐酒许同杯。","淮海春多雨，蒹葭夜有雷。","遥知拜庆后，梅尉称仙才。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-313f41fa-0152-4b99-81d2-ee96ff20a074","tags":[]},{"id":"poem-cb3081d16c39e5556997f554","title":"泊小姑山","author":"陈造","dynasty":"宋","verses":["楚山屹两姑，我见乃其稚。","闻名诗卷间，识面客舟次。","玉刻极端丽，簪植瞑苍翠。","娟月上天角，相与诧妩媚。","怒风将我西，未憗卜晚憩。","山足舟可舣，山木缆可系。","山外正风波，独此佳食寐。","断知有神物，主此胜绝地。","明朝捐行橐，可无答神赐。","白鹅雪为肪，绿蚁香馥鼻。","舟稳风又熟，无乃契神意。","未暇访彭郎，辞费辨非是。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-1a24bb66-8ee3-49da-9c08-8929378b5d86","tags":[]},{"id":"poem-cb32d77c397dcd4f4f2d6800","title":"古歌行","author":"高适","dynasty":"唐","verses":["君不见汉家三叶从代至，高皇旧臣多富贵。","天子垂衣方晏如，庙堂拱手无余议。","苍生偃卧休征战，露台百金以为费。","田舍老翁不出门，洛阳少年莫论事。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-32ade105-6639-4a2d-8ba5-afb25200c6b3","tags":[]},{"id":"poem-cb40942462ae38f64a8ef5bd","title":"题宇文秀才樱桃","author":"李涉","dynasty":"唐","verses":["风光莫占少年家，白发殷勤最恋花。","今日颠狂任君笑，趂愁得醉眼麻茶。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-bc669dfe-f2a1-4943-8995-09a55eb09188","tags":[]},{"id":"poem-cb45921df9b5efb073417a8f","title":"君子行","author":"李咸用","dynasty":"唐","verses":["君子慎所履，小人多所疑。","尼甫至圣贤，犹为匡所縻。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-b28c27f1-881e-416c-8da4-78cfa97903fd","tags":[]},{"id":"poem-cb47d75bdd3a45d47d02af30","title":"和杨直讲寒食感怀","author":"苏颂","dynasty":"宋","verses":["永日轻风起暝阴，伤春情绪苦难禁。","流连节物游人意，怅惜时光志士心。","桃李新芳添远思，龙蛇遗事感悲吟。","知君退直饶欢趣，每向尊前赏奏音。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-8ce405a4-969b-4306-b071-db5ec61e0820","tags":[]},{"id":"poem-cb502783f686a3a77b2102ec","title":"偈十六首  其四","author":"释士珪","dynasty":"宋","verses":["东林百不会，瞎驴随大队。","鞭打不进前，步步只倒退。","一日复一日，灵台转昏昧。","死去入地狱，永劫终不悔。","开口见心肝，实语当忏悔。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-fe5000cc-34c1-4651-980a-a6ad3bc70a0c","tags":[]},{"id":"poem-cb52b6133bb90b70cdc183ee","title":"赠谭先生","author":"杨徽之","dynasty":"唐","verses":["古观重重遶翠微，杉松深处掩双扉。","云生万壑投龙去，海隔三山放鹤归。","花洞宴游春日永，石坛朝礼曙星稀。","每听高论长生理，拟向尘中便拂衣。","（见《瀛奎律髓》卷四十八《仙逸类》。","此诗明李蔉所辑《宋艺圃集》作李九龄诗。","按徽之又有《禁林䜩会之什》一首见于《翰苑群书》者，系入禋后所作，不收录。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-b82e4931-af00-4667-882f-900b181839c8","tags":[]},{"id":"poem-cb54b070d3916a6c80517fc2","title":"寒食日献郡守","author":"伍唐珪","dynasty":"唐","verses":["入门堪笑复堪怜，三径苔荒一钓船。","慙愧四隣教断火，不知厨里久无烟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-6163908f-5c01-47d1-b46c-0f61a2b28717","tags":[]},{"id":"poem-cb665562476f4e9726b09a2c","title":"前腔","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["百年姻眷，须教情愿。","他那里抵死推辞，俺这里不索留恋。","想他每就里，有些儿牵绊。","怕恩多成怨。","满皇都少甚么公侯子，何须去嫁状元？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5017","tags":[]},{"id":"poem-cb665d927e4a2d2e778b53ec","title":"和三乡诗","author":"王硕","dynasty":"唐","verses":["无姓无名越水滨，芳词空怨路傍人。","莫教才子偏惆怅，宋玉东家是旧邻。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-10ddafb1-fd9a-42a2-82c4-16e28862cde8","tags":[]},{"id":"poem-cb672ef91356abdc704dce84","title":"寄怀楚和尚二首 一","author":"贯休","dynasty":"唐","verses":["吾师师子儿，而复貌瓌奇。","何得文明代，不为王者师。","铁盂汤雪早，石炭煮茶迟。","谩有参寻意，因循到乱时。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-fb9130e8-b244-43a3-9033-39b7a9b55ad6","tags":[]},{"id":"poem-cb6fae1fc899da8b3382505a","title":"得胜令","author":"杨景贤","dynasty":"元","verses":["长老便是正名师，(刘云)那得小和尚来告状，他是谁？(夫人唱)天网恢恢，疏而不漏，这个是江流的小孩儿。","今日个死草重交翠，残花再发枝。","当时，已趁英雄志，你不索寻思，则要你填还俺夫婿死。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-7970","tags":[]},{"id":"poem-cb83972be151812af6ec6ec6","title":"横吹曲辞 前出塞九首 七","author":"杜甫","dynasty":"唐","verses":["驱马天雨雪，军行入高山。","迳危抱寒石，指落曾冰间。","已去汉月远，何时筑城还？","浮云暮南征，可望不可攀。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-68f3ddee-deaa-484e-b375-0b6eed8bb3b9","tags":[]},{"id":"poem-cb8a5f152b3ae145e3781654","title":"元和直言诗","author":"张祜","dynasty":"唐","verses":["东野小臣祜，圣朝垂泪言。","微尘岂裨助，永负丘山恩。","箕子昔为奴，所悲逢世昏。","明时便钳舌，切恐负乾坤。","臣当涉黄河，心目日且烦。","分明在人世，不喻波浑浑。","愿以所支流，却寻到昆仑。","但穷此生感，没齿宁为寃。","臣读帝王书，粗知治乱源。","文思苟未安，讵得宾四门。","陛下欲垂衣，一与夔契论。","成汤事不尽，勿更随波翻。","直者举其材，曲者寻其根。","直固不可遗，曲亦不可焚。","用材苟端审，帝道即羲轩。","陛下复土阶，四方敢高垣。","陛下喜雕墙，四方必重藩。","畋猎岂无娱，汤泉岂无温。","始知尧为心，清净自成尊。","比干不惮死，谏道久而存。","许由不务策，志士亦所敦。","兢兢小臣祜，万死甘词繁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-9f48917a-e5a1-4013-b538-0e6995727431","tags":["黄河"]},{"id":"poem-cb8c5bb4141e6230b170e292","title":"将归蜀留献恩地仆射二首 一","author":"姚鹄","dynasty":"唐","verses":["自持衡镜采幽沈，此事常闻旷古今。","危叶只将终委地，焦桐谁料却为琴。","蒿莱讵报生成德，犬马空怀感恋心。","明日还家盈眼血，定应回首即沾襟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-2b5920c0-c1a7-44c7-8d14-48c22657b8a5","tags":[]},{"id":"poem-cb8f34e9ef43c497b817d83c","title":"经王先生故居","author":"赵嘏","dynasty":"唐","verses":["晚波东去海茫茫，谁识蓬山不死乡。","弄玉已归萧史去，碧楼红树倚斜阳。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-94f49863-1b47-4373-b109-3833d2626a41","tags":[]},{"id":"poem-cb8f8a139322e85b5ddb5f12","title":"和韦开州盛山十二首 盘石磴","author":"张籍","dynasty":"唐","verses":["垒石盘空远，层层势不危。","不知行几匝，得到上头时。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-0ea9fab0-d3c4-4ed6-8234-f78a1ae68cbb","tags":[]},{"id":"poem-cb911d5ad9b30b680f9fabfb","title":"送沈单作尉江都","author":"赵嘏","dynasty":"唐","verses":["炀帝都城春水边，笙歌夜上木兰船。","三千宫女自涂地，十万人家如洞天。","焰焰花枝官舍晚，重重云影寺墙连。","少年作尉须矜慎，莫向楼前坠马鞭。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-b9ab718a-6cf2-4b9e-a6d7-8e6f79254e26","tags":[]},{"id":"poem-cb915ba2605cd26f37762563","title":"夜别韦司士得城字","author":"高适","dynasty":"唐","verses":["高馆张灯酒复清，夜钟残月雁归声。","只言啼鸟堪求侣，无那春风欲送行。","黄河曲里沙为岸，白马津边柳向城。","莫怨他乡暂离别，知君到处有逢迎。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-dddc5861-5ad3-438a-999e-f068b10fc886","tags":["黄河","离别","饮酒","惜别","友情"]},{"id":"poem-cb93442f89382b149ade6f00","title":"望梅花·春草全无消息","author":"和凝","dynasty":"五代","verses":["春草全无消息，腊雪犹余踪迹。","越岭寒枝香自坼，冷艳奇芳堪惜。","何事寿阳无处觅，吹入谁家横笛。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-6-juan.json#record-23","tags":[]},{"id":"poem-cb96f4c2c41410ad2dded49d","title":"山中答刘书记寓怀","author":"李山甫","dynasty":"唐","verses":["贵门多冠冕，日与荣辱并。","山中有独夫，笑傲出衰盛。","正直任天真，鬼神亦相敬。","之子贲丘园，户牖松萝暎。","骨将槁木齐，心同止水净。","笔头指金波，座上横玉柄。","芙蓉出秋渚，绣段流清咏。","高古不称时，沉默岂相竞。","穷搜万籁息，危坐千峰静。","林僧继嘉唱，风前亦为幸。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-81c42920-e893-4820-a655-cb1622d80487","tags":[]},{"id":"poem-cb98d564ea239844f5daa368","title":"鞭春行","author":"林光朝","dynasty":"宋","verses":["辘轳罥寒田雀饥，江梅落蛀兔脚肥。","枯肠一夜转双毂，眼光吹上虾蟆衣。","岩腹新晴山鬼哭，女娲坟外春风归。","茧村纸帘大如席，拆拆藜杖金雀飞。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-c97e8a15-d98b-4958-be23-658f8da76145","tags":[]},{"id":"poem-cb99693550f7bcd3fae4392a","title":"同前换头","author":"无名氏《张协状元》","dynasty":"元","verses":["我婆且自宽心，张协为人恁底村，婆要镜，没时岂敢上婆门。","(净)拜辞君，我和伊今夜有人相请，隔岸村庄祭土神。","(未白)只为吃。","(净连唱)你道婆婆，怎地了脚头紧。","(末)好不安分！(末净下)(旦又唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2584","tags":[]},{"id":"poem-cba0d2684bf595aeffec8604","title":"浣沙溪・浣溪沙·不为萧娘旧约寒","author":"周邦彦","dynasty":"宋","verses":["不为萧娘旧约寒。","何因容易别长安。","预愁衣上粉痕干。","幽阁深沈灯焰喜，小炉邻近酒杯宽。","为君门外脱归鞍。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-462","tags":[]},{"id":"poem-cba973335e19046dc50faf66","title":"适南亭","author":"华镇","dynasty":"宋","verses":["子真埋照地，千载委榛莽。","知音久未会，遗踪寂谁赏。","华堂始基搆，皂盖日来往。","高风邈已远，兹焉竞长想。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-aa0743e8-3c10-4d4d-9250-3ccc724ad185","tags":[]},{"id":"poem-cbbc97ffc8bdfb1d35e20bda","title":"郡斋夜坐闻水车声  其二","author":"王十朋","dynasty":"宋","verses":["天二欲警老刺史，车声夜入凝香耳。","四郊苗槁农民悲，万壑水干鱼鼈死。","守臣失职政事荒，谁遣连年坐黄堂。","自惭不及段文昌，圣世岂有桑弘羊。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-3750bfd0-00e4-4971-bc71-f365b1145e45","tags":[]},{"id":"poem-cbc6e99005c16755dd139754","title":"和伯常自郢州见寄","author":"司马光","dynasty":"宋","verses":["西郊去歳揖行人，柳暗花浓又一春。","坐想高风清入骨，沉吟佳句健生神。","潺湲杳霭烟波古，散诞逍遥兴趣新。","应笑洛阳车马道，缁衣未免化红尘。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-f71d1748-9f8a-4f92-b490-682e6517be47","tags":[]},{"id":"poem-cbc912bb496bcb12bcb5a4d8","title":"霜天晓角·霜清水碧","author":"高观国","dynasty":"宋","verses":["霜清水碧。","冷浸红云湿。","休说季伦锦帐，山南岸、更花密。","露滴。","空翠幂。","两峰开霁色。","不为浓妆一醉，西风帽、为谁侧。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-390","tags":[]},{"id":"poem-cbd204972d3a663f11f0cca5","title":"望秦川","author":"李颀","dynasty":"唐","verses":["秦川朝望迥，日出正东峰。","远近山河净，逶迤城阙重。","秋声万户竹，寒色五陵松。","有客归欤叹，凄其霜露浓。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-望秦川","tags":[]},{"id":"poem-cbd5433675622d834ef23c99","title":"别雒下一二知己","author":"谭用之","dynasty":"宋","verses":["金鼎光辉照雪袍，雒阳春梦忆波涛。","尘埃满眼人情异，风雨前程马足劳。","接塞峨眉通蜀险，过山仙掌倚秦高。","别来无限幽求子，应笑区区味六韬。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-2edb670c-ce7d-4992-bf14-9226ab8d3e57","tags":[]},{"id":"poem-cbef7ad737c42c711feb5b95","title":"紫萸香慢·近重阳、偏多风雨","author":"姚云文","dynasty":"宋","verses":["近重阳、偏多风雨，绝怜此日暄明。","问秋香浓未，待携客、出西城。","正自羁怀多感，怕荒台高处，更不胜情。","向尊前、又忆洒酒插花人。","只座上、已无老兵。","凄情。","浅醉还醒。","愁不肯、与诗平。","记长楸走马，雕弓笮柳，前事休评。","紫萸一枝传赐，梦谁到、汉家陵。","尽乌纱、便随风去，要天知道，华发如此星星。","歌罢涕零。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-254","tags":["宋词三百首"]},{"id":"poem-cbf4d4293500b632cb7fefe5","title":"游瀍上刘氏园","author":"司马光","dynasty":"宋","verses":["日暖孤台迥，露浓幽迳微。","茅斋举白饮，沙溆踏青归。","照水清满眼，穿林香湿衣。","莫言春尚浅，已有杏花飞。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-bf674e1c-ef09-4ee8-9d6e-1f8f43afab38","tags":[]},{"id":"poem-cbf7027d113d4e32575657d4","title":"奉送李中丞道昌入朝","author":"皎然","dynasty":"唐","verses":["文宪中司盛，恩荣外镇崇。","诸侯皆取则，八使独推功。","诏喜新衔凤，车看旧饰熊。","去思今武子，余教昔文翁。","清在如江水，仁留是国风。","光征二千石，扫第望司空。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-12bba4b4-3689-4142-9366-1334d7305fc8","tags":[]},{"id":"poem-cbf797b81a67608ae73a86c7","title":"望江南・忆江南·临川好","author":"谢逸","dynasty":"宋","verses":["临川好，柳岸转平沙。","门外澄江丞相宅，坛前乔木列仙家。","春到满城花。","行乐处，舞袖卷轻纱。","谩摘青梅尝煮酒，旋煎白雪试新茶。","明月上檐牙。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-654","tags":[]},{"id":"poem-cbfc48bacda516b11b5181af","title":"郊庙歌辞 封泰山乐章 太和","author":"张说","dynasty":"唐","verses":["孝敬中发，和容外彰。","腾华照宇，如升太阳。","贞璧就奠，玄灵垂光。","礼乐具举，济济洋洋。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-22c07619-9423-4f39-be66-e5380527651b","tags":["泰山"]},{"id":"poem-cc0601f6ef6c09f52e5b7f39","title":"酬王哦松八景  其四","author":"释居简","dynasty":"宋","verses":["噎噎梅花煖响初，晓来痕绿到蘼芜。","鹗沈鹦鹉千年恨，指旧江山忍按图。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-a6bfba67-90a8-4835-b68c-41a6f7f2ce8f","tags":[]},{"id":"poem-cc10cc55e257978de8dfd306","title":"句  其二","author":"牟及","dynasty":"宋","verses":["困雨葵心终向日，随风柳絮慢漫天。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-5c6e263c-b239-47f6-b39a-6bb3dc7b050e","tags":[]},{"id":"poem-cc2d7310d6017e433e9fba4c","title":"和乐天春词","author":"刘禹锡","dynasty":"唐","verses":["新妆面面下朱楼，深锁春光一院愁。","行到中庭数花朵，蜻蜓飞上玉搔头。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-297dd100-6aab-4685-a52d-983fb0999c7a","tags":["唐诗三百首","孤独","春天","女子","七言绝句"]},{"id":"poem-cc3ecd66e90d71ae8b1beb70","title":"句 二","author":"廖凝","dynasty":"唐","verses":["千山景象通。","（《江湖小集》卷四绍嵩《江浙纪行集句诗》引）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-8470bc42-a153-48e5-9290-e1b64f3c6602","tags":[]},{"id":"poem-cc52541e8f47201b085a9ff6","title":"和李舍人直中书对月见寄","author":"李端","dynasty":"唐","verses":["名卿步月正淹留，上客裁诗怨别游。","素魄近成班女扇，清光远似庾公楼。","婵娟更称凭高望，皎洁能传自古愁。","盈手入怀皆不见，阳春曲丽转难酬。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-668bda10-2fcd-45a3-9795-a8393e22ae00","tags":[]},{"id":"poem-cc56fd847b69f4954a4082bd","title":"瀑布","author":"王镃","dynasty":"宋","verses":["青天隠隠响晴雷，绝顶流来不知处。","巨灵怒擘两山开，飞下玉龙归海去。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-d7da3308-565a-4c3e-b485-5621da9e0582","tags":[]},{"id":"poem-cc580dc337708df2073d5ce9","title":"上巳日陪襄阳李尚书宴光风亭","author":"刘言史","dynasty":"唐","verses":["碧池萍嫩柳垂波，绮席丝镛舞翠娥。","为报会稽亭上客，永和应不胜元和。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-029fca99-9c54-464e-b862-f3a7acc7a1be","tags":[]},{"id":"poem-cc58e6eb8fa6efade56197cc","title":"思越人·翠屏欹","author":"鹿虔扆","dynasty":"五代","verses":["翠屏欹，银烛背，漏残清夜迢迢。","双带绣窠盘锦荐，泪浸花暗香消。","珊瑚枕腻鸦鬟乱，玉纤慵整云散。","若是适来新梦见，离肠怎不千断。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-9-juan.json#record-17","tags":[]},{"id":"poem-cc598c4fc27f184f13a5a210","title":"春游曲","author":"文德皇后","dynasty":"唐","verses":["上苑桃花朝日明，兰闺艳妾动春情。","井上新桃偷面色，檐边嫩柳学身轻。","花中来去看舞蝶，树上长短听啼莺。","林下何须远借问，出众风流旧有名。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-a25186df-0de3-49e6-81f2-2cc5c0853b43","tags":[]},{"id":"poem-cc6397c97a6509341773161a","title":"感事十诗上李侍郎  其四","author":"陈造","dynasty":"宋","verses":["国工铸良剑，发白心志悴。","晶荧淬歛余，干莫并犀利。","入匣蛰虬龙，落手慑魑魅。","卫身未足道，适用在一试。","楼兰犹颉颃，顾汝岂虚器。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-b3a95a7f-cfd5-4fba-8c51-d44016b3e216","tags":[]},{"id":"poem-cc6680c7d7877ed408781287","title":"寄左省杜拾遗","author":"岑参","dynasty":"唐","verses":["联步趋丹陛，分曹限紫薇。","晓随天仗入，暮惹御香归。","白发悲花落，青云羡鸟飞。","圣朝无阙事，自觉谏书稀。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-寄左省杜拾遺","tags":[]},{"id":"poem-cc6c9b92ffd6de841298250d","title":"追赋画江潭苑四首 三","author":"李贺","dynasty":"唐","verses":["剪翅小鹰斜，[縚]根玉旋花。","秋垂妆钿粟，箭箙钉文牙。","●●啼深竹，䴔䴖老湿沙。","宫官烧蜡火，飞烬汚铅华。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-7cb76c4b-f352-4602-b624-e1f1e882810f","tags":[]},{"id":"poem-cc6fa7e39e5ad41a02a512d3","title":"水调歌头·落日塞垣路","author":"刘潜","dynasty":"宋","verses":["落日塞垣路，风劲戛貂裘。","翩翩数骑闲猎，深入黑山头。","极目平沙千里，惟见雕弓白羽，铁面骇骅骝。","隐隐望青冢，特地起闲愁。","汉天子，方鼎盛，四百州。","玉颜皓齿，深锁三十六宫秋。","堂有经纶贤相，边有纵横谋将，不作翠蛾羞。","戎虏和乐也，圣主永无忧。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-573","tags":[]},{"id":"poem-cc7020e02c36a6399b0d47d1","title":"客舍喜友人相访","author":"贺兰朋吉","dynasty":"唐","verses":["荒居无四隣，谁肯访来频。","古树秋中叶，他乡病里身。","鴈声风送急，萤影月流新。","独为成名晚，多慙见友人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-7be8bb2b-1e40-4e51-8632-98e33d27f5e5","tags":[]},{"id":"poem-cc77fbc80647c84a6004d8e3","title":"渔家傲·几日北风江海立","author":"胡舜陟","dynasty":"宋","verses":["几日北风江海立。","千车万马鏖声急。","短棹峭寒欺酒力。","飞雨息。","琼花细细穿窗隙。","我本绿蓑青箬笠。","浮家泛宅烟波逸。","渚鹭沙鸥多旧识。","行未得。","高歌与尔相寻觅。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-596","tags":[]},{"id":"poem-cc7818f650392bff868b8b0d","title":"哭许崧老右丞二首  其一","author":"李纲","dynasty":"宋","verses":["夫子相知一纪前，定交握手自忘年。","长松老鹤骨格古，粹玉精金操守坚。","出入三朝昭大节，漂流万里正华颠。","皇天不愸遗元老，空使苍生共黯然。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-b17f6c07-9436-4d50-8cfe-7221fd9db6e1","tags":[]},{"id":"poem-cc8168d789f65914876e3064","title":"赠王建","author":"张籍","dynasty":"唐","verses":["白君去后交游少，东野亡来箧笥贫。","赖有白头王建在，眼前犹见咏诗人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-b5d817cf-5bc3-489c-a7a0-3c8579c679bd","tags":[]},{"id":"poem-cc81d36bb38638dfc9561be2","title":"酒泉子·寂寞青楼","author":"李珣","dynasty":"五代","verses":["寂寞青楼，风触绣帘珠碎撼。","月朦胧，花暗淡，锁春愁。","寻想往事依稀梦，泪脸桃红色重。","鬓欹蝉。钗坠凤，思悠悠。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-x-juan.json#record-37","tags":[]},{"id":"poem-cc8b6bf6c16f6a674af65098","title":"送梁拾遗肃归朝","author":"皎然","dynasty":"唐","verses":["明主重文谏，才臣出江东。","束书辞东山，改服临北风。","万里望皇邑，九重当曙空。","天开芙蓉阙，日上蒲桃宫。","天子初未起，金闺籍先通。","身逢轩辕世，名贵鸳鸾中。","故人荣此别，何用悲丝桐。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-1478521e-b545-4d8c-9775-c9063f3f7c70","tags":[]},{"id":"poem-cc8ccee231fa18645c39cdaa","title":"河满子·寂寞芳菲暗度","author":"毛熙震","dynasty":"五代","verses":["寂寞芳菲暗度，岁华如箭堪惊。","缅想旧欢多少事，转添春思难平。","曲槛丝垂金柳，小窗弦断银筝。","深院空闻燕语，满园闲落花轻。","一片相思休不得，忍教长日愁生。","谁见夕阳孤梦，觉来无限伤情。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-x-juan.json#record-0","tags":[]},{"id":"poem-cc94b2fd9bbd1b15d9b83d95","title":"丰干闾丘虎赞","author":"释了惠","dynasty":"宋","verses":["虎怕人心恶，人欺虎太慈。","虽逢贤太守，难打者官司。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-00ac77a0-875e-4b2d-80b6-78e4743233cf","tags":[]},{"id":"poem-cc9b10c7db951e55127ee87b","title":"伯兮","author":"佚名","dynasty":"先秦","verses":["伯兮朅兮，邦之桀兮。伯也执殳，为王前驱。","自伯之东，首如飞蓬。岂无膏沐？谁适为容！","其雨其雨，杲杲出日。愿言思伯，甘心首疾。","焉得谖草？言树之背。愿言思伯。使我心痗。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-61","tags":[]},{"id":"poem-cca37c5004267f08e3b7c26f","title":"更漏子 其一","author":"温庭筠","dynasty":"唐","verses":["柳丝长，春雨细，花外漏声迢递。","惊塞雁，起城乌，画屏金鹧鸪。","香雾薄，透帘幕，惆怅谢家池阁。","红烛背，绣帘垂，梦长君不知。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-1-juan.json#record-14","tags":[]},{"id":"poem-ccacbcec9ee17eddfa6c6581","title":"接贤宾·香鞯镂襜五花骢","author":"毛文锡","dynasty":"五代","verses":["香鞯镂襜五花骢，值春景初融。","流珠喷沫躞蹀，汗血流红。","少年公子能乘驭，金镳玉辔珑璁。","为惜珊瑚鞭不下，骄生百步千踪。","信穿花，从拂柳，向九陌追风。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-5-juan.json#record-11","tags":[]},{"id":"poem-ccb0ccd4d40eba658b874296","title":"惜花","author":"张籍","dynasty":"唐","verses":["山中春已晚，处处见花稀。","明日来应尽，林间宿不归。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-1aee5e51-52a5-4f6d-9271-a95b47d1db12","tags":[]},{"id":"poem-ccb6b6c75b018097f7562be1","title":"八声甘州","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["(外)春深离故家，叹衰年倦体，奔走天涯。","一鞭行色，遥指剩水残霞。","墙头嫩柳篱畔花，见古树枯藤栖暮鸦。","嗟呀！遍长途触目桑麻。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8307","tags":[]},{"id":"poem-ccb98002d0e5c387bc793a3e","title":"不食姑","author":"张籍","dynasty":"唐","verses":["几年山里住，已作绿毛身。","护气常稀语，存思自见神。","养龟同不食，留药任生尘。","要问西王母，仙中第几人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-4ecad10d-5ac7-423f-b2bd-bb86f0e21b39","tags":[]},{"id":"poem-ccbf08b79b6ee37396ae376c","title":"诉衷情·长桥春水拍堤沙","author":"仲殊","dynasty":"宋","verses":["长桥春水拍堤沙。","疏雨带残霞。","几声脆管何处，桥下有人家。","宫树绿，晚烟斜。","噪闲鸦。","山光无尽，水风长在，满面杨花。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-912","tags":[]},{"id":"poem-ccbff3e63b9fe1e58bbb20e9","title":"鹭鸶","author":"裴说","dynasty":"唐","verses":["秋江清浅时，鱼过亦频窥。","却为分明极，翻成所得迟。","浴偎红日色，栖压碧芦枝。","会共鹓同侣，翺翔应可期。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-3cb2e663-bb27-40b3-abec-ba6ff12afce9","tags":[]},{"id":"poem-ccc47a0d78e53cdd3064482d","title":"怀尹真人","author":"鲍溶","dynasty":"唐","verses":["万里叠嶂翠，一心浮云闲。","羽人杏花发，倚树红琼颜。","流水杳冥外，女萝阴荫间。","却思人间世，多恐不可还。","青鸟飞难远，春云晴不闲。","但恐五云车，山上复有山。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-cdc7299a-dc10-4829-8514-7f6674b06ee7","tags":[]},{"id":"poem-ccc5ecb9317ca9048775ae8b","title":"酬苏员外味道夏晚寓直省中见赠","author":"沈佺期","dynasty":"唐","verses":["并命登仙阁，分曹直礼闱。","大官供宿膳，侍史护朝衣。","卷幔天河入，开窗月露微。","小池残暑退，高树早凉归。","冠劒无时释，轩车待漏飞。","明朝题汉柱，三署有光辉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-d8e61a77-dc28-4e92-a954-fbfa49eabdde","tags":[]},{"id":"poem-ccd2494e2f5b3d7c599cc715","title":"归国遥·金翡翠","author":"韦庄","dynasty":"五代","verses":["金翡翠，为我南飞传我意。","罨画桥边春水，几年花下醉。","别后只知相愧，泪珠难远寄。","罗幕绣帷鸳被，旧欢如梦里。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-2-juan.json#record-39","tags":[]},{"id":"poem-ccda1ea2228240e6daaae503","title":"山居诗  其九","author":"释延寿","dynasty":"宋","verses":["幽斋独坐绝参详，兀尔何如骤世忙。","拯济终凭宏愿力，安闲须得守愚方。","柴门半掩花空落，苔径虚踪草自荒。","最好静中无一事，翛然唯得道芽长。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-3826c3a3-65d9-497f-9418-5e8264dbe3b5","tags":[]},{"id":"poem-ccda490074e0ecadf16c73ed","title":"句","author":"季方","dynasty":"唐","verses":["林间纵有残花在，留到明朝不是春。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-f92c91e0-7015-482a-bd22-e648b7b37725","tags":[]},{"id":"poem-ccef542b229e2d1c62f406f0","title":"以人葠遗段成式","author":"周繇","dynasty":"唐","verses":["人形上品传方志，我得真英自紫团。","慙非叔子空持药，更请伯言审细看。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-65458e44-c424-4a6b-a163-653449878f4a","tags":[]},{"id":"poem-ccf50e4555e156c01e41f48d","title":"峨眉","author":"杨徽之","dynasty":"宋","verses":["嘉州山水地，二蜀最为美。","翠岭叠峨眉，长澜涌锦水。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-93c4dadf-42f9-45c1-a45f-70e817318bb8","tags":[]},{"id":"poem-ccfa44d647ae6d51447f25a6","title":"送默然上人归天台","author":"王镃","dynasty":"宋","verses":["孤云不定心，持钵度寒林。","野饭青蒲洁，秋程黄叶深。","海风潮水发，山雨晓烟沉。","归到石桥日，应看瀑布吟。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-0760ab2a-2fa9-4dde-9847-a13ad3fe1720","tags":[]},{"id":"poem-ccfc674b6a6bfb5744ad271d","title":"桃源行","author":"王维","dynasty":"唐","verses":["渔舟逐水爱山春，两岸桃花夹去津。","坐看红树不知远，行尽青溪不见人。","山口潜行始隈隩，山开旷望旋平陆。","遥看一处攒云树，近入千家散花竹。","樵客初传汉姓名，居人未改秦衣服。","居人共住武陵源，还从物外起田园。","月明松下房栊静，日出云中鸡犬喧。","惊闻俗客争来集，竞引还家问都邑。","平明闾巷埽花开，薄暮渔樵乘水入。","初因避地去人间，及至成仙遂不还。","峡里谁知有人事，世中遥望空云山。","不疑灵境难闻见，尘心未尽思乡县。","出洞无论隔山水，辞家终拟长游衍。","自谓经过旧不迷，安知峰壑今来变。","当时只记入山深，青溪几曲到云林。","春来遍是桃花水，不辨仙源何处寻。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-3b847cf5-16b1-449d-a436-e5995c6433c4","tags":["唐诗三百首","写景","乐府","新乐府辞","水"]},{"id":"poem-ccfd8e3617924433a62a5f4d","title":"玉楼春·华堂夜宴连清晓","author":"吴文英","dynasty":"宋","verses":["华堂夜宴连清晓。","醉里笙歌云窈袅。","酿来千日酒初尝，过却重阳秋更好。","阿儿早晚成名了。","玉树阶前春满抱。","天边金镜不须磨，长与妆楼悬晚照。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-454","tags":[]},{"id":"poem-ccff6a6159e5d7cbc07d314e","title":"子庆诗","author":"孟郊","dynasty":"唐","verses":["王家事已奇，孟氏庆无涯。","献子还生子，羲之又有之。","凤兮且莫叹，鲤也会闻诗。","小小豫章甲，纤纤玉树姿。","人来唯仰乳，母抱未知慈。","我欲拣其养，放麛者是谁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-a6062777-a23a-4e6f-8362-843f251c4a0e","tags":[]},{"id":"poem-cd004b3ee40561e9ccdfd81a","title":"江行望匡庐","author":"钱起","dynasty":"唐","verses":["咫尺愁风雨，匡庐不可登。","只疑云雾窟，犹有六朝僧。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-江行望匡廬","tags":[]},{"id":"poem-cd061d54951386f70f68ff55","title":"虞美人·鸳鸯对浴银塘暖","author":"毛文锡","dynasty":"五代","verses":["鸳鸯对浴银塘暖，水面蒲稍短。","垂杨低拂曲尘波，蛛丝结网露珠多，滴圆荷。","遥思桃叶吴江碧，便是天河隔。","锦鳞红鬣影沉沉，相思空有梦相寻，意难任。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-5-juan.json#record-4","tags":[]},{"id":"poem-cd09c2a53551c94930488503","title":"茤谷","author":"释居简","dynasty":"宋","verses":["赋就垂天起隠沦，鹜飞难并鹄亭亭。","池塘早已腾春馥，龙麝何烦乱德馨。","虚应有神元不死，静观无物不长灵。","双眸弗见南州士，莫作西山雨后青。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-1c6446ed-10e9-4ccb-a122-ceebe0ea52ce","tags":[]},{"id":"poem-cd1222f2816773137bbf6bb8","title":"江上逢故人","author":"崔道融","dynasty":"唐","verses":["故里琴樽侣，相逢近腊梅。","江村买一醉，破泪却成咍。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-92f7c036-50fb-4b99-985b-d57199c9dbf0","tags":[]},{"id":"poem-cd1276135a61e1061edf758a","title":"再次前韵二首呈士秀  其一","author":"曾协","dynasty":"宋","verses":["相逢此日胜平生，不厌搘筇数送迎。","乐地共欣三径就，诗坛仍见一军惊。","风飘柳线曾经染，雪著梅梢分外清。","光景唤人无计奈，剩烦佳句破愁城。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-7fe9c499-4504-4698-a466-5be31db1d71d","tags":[]},{"id":"poem-cd18f6c70454a650d1cff1e7","title":"秋月收兵献钟侍郎","author":"茹芝翁","dynasty":"宋","verses":["强兵义勇威严令，化靖由来不战征。","疆境复时归马健，鼓鼙休处乱云轻。","霜凝积恨怀边戍，月落冲寒夜上城。","黄叶树头风凛凛，碧波江远路平平。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-ea3f7ea8-124a-4acf-9979-9040059ee827","tags":[]},{"id":"poem-cd2094553e6e81fbf148cf89","title":"酬舒公见寄","author":"唐求","dynasty":"唐","verses":["无客不言云外见，为文长遣世间知。","一声松径寒吟后，正是前山雪下时。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-9bfee45f-5958-4cfa-a8fb-42536c22acaa","tags":[]},{"id":"poem-cd23fec43994a48a501b8ff6","title":"双劝酒","author":"无名氏《张协状元》","dynasty":"元","verses":["阿爹阿娘，教我传语：些儿酒米，担来与你。","要时你便留住，不要我便将去。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2517","tags":[]},{"id":"poem-cd3c1edfdeaf1bf8fac003c0","title":"过晋阳宫","author":"明皇帝","dynasty":"唐","verses":["缅想封唐处，实惟建国初。","俯察伊晋野，仰观乃参虚。","井邑龙斯跃，城池凤翔余。","林塘犹沛泽，台榭宛旧居。","运革祚中否，时迁命兹符。","顾循承丕构，怵惕多忧虞。","尚恐威不逮，复虑化未孚。","岂徒劳辙迹，所期训戎车。","习俗问黎人，亲巡慰里闾。","永言念成功，颂德临康衢。","长怀经纶日，叹息履庭隅。","艰难安可忘，欲去良踟蹰。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-d0337427-89fa-44ca-8f08-6f989572feb6","tags":[]},{"id":"poem-cd3ce99dd630a2f49239e4fc","title":"集贤宾","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["一阳气转春透彻，履长欢庆冬节。","验岁瞻云人意切，听残漏晓临台榭。","今年是别，黄云谶争书吉贴。","(合)芳宴设，沉醉后，管弦声咽。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8325","tags":[]},{"id":"poem-cd3fec589c6606df9412d554","title":"小桃红","author":"杨景贤","dynasty":"元","verses":["咚咚地小鬼擂征鼙，不怕你会使拖刀计。","待俺将不强不弱的铁胎弓，一拈千转的狼牙箭，去射这厮。","饶他有千般变幻身躯，怎当我百步穿杨手段？(做射科)(佛做莲花遮科)(鬼母唱)蹬弩开弓那威势，一箭箭往前射，则见他金莲朵朵遮胸臆。","早难道射不主皮，他元来温而不厉，险恼杀这个搽胭粉的养由基。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-10331","tags":[]},{"id":"poem-cd484e7464d5894da1ad9101","title":"送灵云和尚颂（题拟）","author":"慧救","dynasty":"唐","verses":["谛当恒然直古今，未彻见闻实甚深。","现现运转三十载，春尽萎花未君心。","（《祖堂集》卷十九。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-59464be1-8260-43ce-939a-85e677ba21d1","tags":[]},{"id":"poem-cd500813cceca2d5f01aea27","title":"句 五","author":"李煜","dynasty":"五代","verses":["别易会难无可奈。","（见《能改斋漫录》卷十六。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-68c39d23-2946-48a1-8110-1bfe2c02e111","tags":[]},{"id":"poem-cd5688765067808edfad4142","title":"虞美人·春风曾见桃花面","author":"张景修","dynasty":"宋","verses":["春风曾见桃花面。","重见胜初见。","两枝独占小春开。","应怪刘郎迷路、又重来。","旁人应笑髯公老。","独爱花枝好。","世间好景不长圆。","莫放笙歌归院、且尊前。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-643","tags":[]},{"id":"poem-cd62a63c094aad490f8f6757","title":"蓦山溪·雕弓绣帽","author":"王以宁","dynasty":"宋","verses":["雕弓绣帽。","戏马秦淮道。","风入马啼轻，曾踏遍、淮堤芳草。","飞英点点，春事已阑珊，风雨横，别离多，断送英雄老。","功名终在，休惜芳尊倒。","谈笑下燕云，看千里、风驱电扫。","男儿此事，莫待鬓丝棼，汉都护，万年觞，玉殿春风早。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-64","tags":[]},{"id":"poem-cd63e71ce47227d57f0d869c","title":"紫花序","author":"杨景贤","dynasty":"元","verses":["西天西如来亲送，中国中和尚才行，南海南菩萨来将。","虽然一番受苦，也能勾百世流芳。","斟量，方信道人香千里香，端的是道尊德无上。","今日个送路在山门，抵多少携手上河梁。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-3398","tags":[]},{"id":"poem-cd66212825fd230bf90fdde6","title":"庚戌正月一日游都峤山留五绝句栖真观中  其一","author":"李纲","dynasty":"宋","verses":["元日寻真到洞天，溪边春色已嫣然。","落花流水人间去，谁道桃源不是仙。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-1045c4cd-bc51-4a7d-9517-a28d9ffbfe51","tags":[]},{"id":"poem-cd6bf691138e7e87434e1efc","title":"忆仙姿・如梦令·莲叶初生南浦","author":"贺铸","dynasty":"宋","verses":["莲叶初生南浦。","两岸绿杨飞絮。","向晚鲤鱼风，断送彩帆何处。","凝伫。","凝伫。","楼外一江烟雨。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-50","tags":[]},{"id":"poem-cd707d090a1fb6f3aa53bf69","title":"海边见罗邺","author":"贯休","dynasty":"唐","verses":["清世诗声出，谁人得似君。","命通须有日，天未丧斯文。","楚木寒连寺，修江碧入云。","相思喜相见，庭叶正纷纷。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-25318673-4aef-42c4-89d9-7aed97ab6781","tags":[]},{"id":"poem-cd70958268299c0fa78ffdd5","title":"后庭花·石城依旧空江国","author":"孙光宪","dynasty":"五代","verses":["石城依旧空江国，故宫春色。","七尺青丝芳草碧，绝世难得。","玉英凋落尽，更何人识，野棠如织。","只是教人添怨忆，怅望无极。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-8-juan.json#record-10","tags":[]},{"id":"poem-cd7439ae1e48c0a81875952c","title":"又泛西溪诗十首  其一","author":"刘跂","dynasty":"宋","verses":["溪小才容舴艋舟，一樽聊复寄春流。","纵横不用施篙棹，自在教随水上鸥。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-0b88df6c-1d12-4c8c-8a9d-4cbe2fe50913","tags":[]},{"id":"poem-cd759350d4ce6dcf69ed7dc1","title":"斗黑麻","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["奴深谢公公，便辱许诺。","从来的深恩，怎敢忘却！只怕途路远，体怯弱；病染孤身，力衰倦脚。","(合)孤坟寂寞，路途滋味恶。","两处堪悲，万愁怎摸？(末唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5165","tags":[]},{"id":"poem-cd75a8eaa56e2fd302978626","title":"聒龙谣·紫阙苕峣","author":"赵佶","dynasty":"宋","verses":["紫阙苕峣，绀宇邃深，望极绛河清浅。","霜月流天，锁穹隆光满。","水精宫、金锁龙盘，玳瑁帘、玉钩云卷。","动深思，秋籁萧萧，比人世、倍清燕。","瑶阶回。","玉签鸣，渐秘省引水，辘轳声转。","鸡人唱晓，促铜壶银箭。","拂晨光、宫柳烟微，荡瑞色、御炉香散。","从宸游，前后争趋，向金銮殿。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-531","tags":[]},{"id":"poem-cd77fd6b5b8f4de1a93ff370","title":"送僧游天台","author":"贯休","dynasty":"唐","verses":["囊空心亦空，城郭去腾腾。","眼作么是眼，僧谁识此僧。","歇隈红树久，笑看白云崩。","已有天台约，深秋必共登。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-ff40d41a-7501-4e90-ac9e-62288b730b87","tags":[]},{"id":"poem-cd816aed3856d3c0de6bec56","title":"谒金门·杨柳渡","author":"苏庠","dynasty":"宋","verses":["杨柳渡。","醉著青鞋归去。","点点沙鸥何处所。","十里菰蒲雨。","抖擞向来尘土。","卧看碧山云度。","寄语故时猿鹤侣。","未见心先许。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-680","tags":[]},{"id":"poem-cd825c9a31ce5b94511cbdb2","title":"送荻柴与秀才朱观","author":"徐铉","dynasty":"宋","verses":["羡子清吟处，茅斋面碧流。","解憎莲艳俗，唯欠荻花幽。","鹭立低枝晚，风惊折叶秋。","赠君须种取，不必树忘忧。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-38ff457a-0171-442d-9893-f33b8a245125","tags":[]},{"id":"poem-cd84d393b0d448069727c8a5","title":"春秋战国门 少孺","author":"周昙","dynasty":"唐","verses":["宝贵亲仁与善邻，邻兵何要互相臻。","螳蜋定是遭黄雀，黄雀须访挟弹人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-8c84d0d6-d517-4255-a963-9b92991ba1bc","tags":[]},{"id":"poem-cd859d29ed7fb792b68bba2a","title":"和左司张员外自洛使入京中路先赴长安逢立春日赠韦侍御等诸公","author":"孙逖","dynasty":"唐","verses":["拜郎登省闼，奉使驰车乘。","遥瞻使者星，便是郎官应。","台妙时相许，皇华德弥称。","二陕听风谣，三秦望形胜。","此中暌益友，是日多诗兴。","寒尽岁阴催，春归物华证。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-905d012f-ac6d-4ee2-996d-7bd8a9cda463","tags":[]},{"id":"poem-cd8eae8a0c8b596c5debb2ce","title":"金菊对芙蓉·梧叶飘黄","author":"康与之","dynasty":"宋","verses":["梧叶飘黄，万山空翠，断霞流水争辉。","正金风西起，海燕东归。","凭栏不见南来雁，望故人、消息迟迟。","木樨开后，不应误我，好景良时。","只念独守孤帏。","把枕前嘱付，一旦分飞。","上秦楼游赏，酒𣨼花迷。","谁知别后相思苦，悄为伊、瘦损香肌。","花前月下，黄昏院落，珠泪偷垂。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-319","tags":[]},{"id":"poem-cd925688c98427110a3bd973","title":"萧宅二三子赠答诗二十首 客许石","author":"卢仝","dynasty":"唐","verses":["石公说道理，句句出凡格。","相知贵知心，岂恨主为客。","过须归去来，旦晚上无厄。","主人诚贤人，多应不相责。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-f905ae5b-7950-494f-88b4-44b5d4041f2c","tags":[]},{"id":"poem-cd9264e63b014e5eab2645ae","title":"前腔","author":"刘唐卿《白兔记》","dynasty":"元","verses":["(旦)办志诚，灯供养，献光明照十方。","神通显现，显现花台上。","保佑爹娘，身康无恙。","(合前)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8847","tags":[]},{"id":"poem-cd9a45cd327abe7c546af3bd","title":"如梦令·木叶纷纷归路","author":"纳兰性德","dynasty":"清","verses":["木叶纷纷归路。","残月晓风何处。","消息半浮沈，今夜相思几许。","秋雨，秋雨。","一半西风吹去。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-53","tags":[]},{"id":"poem-cda78ab047615cc9b5238ce9","title":"颂古十九首  其一四","author":"释法全","dynasty":"宋","verses":["耳里种田，满口含烟。","锺馗解舞十八拍，张老乘槎上九天。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-892eb06d-996c-4ceb-bd40-f33a718d308c","tags":[]},{"id":"poem-cdd8d140215ae8c0a39fd908","title":"望江南・忆江南·珠自右","author":"陈朴","dynasty":"宋","verses":["珠自右，飞电入丹城。","内养婴儿盈尺象，时逢九数采阳精。","火向水中生。","烧鬼岳，紫殿势峥嵘。","随意出游寰海内，寐如砂碛卧长鲸。","时序与偕行。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-964","tags":[]},{"id":"poem-cde22f49dab93f8f98c6612b","title":"菩萨蛮·梨花满院飘香雪","author":"毛熙震","dynasty":"五代","verses":["梨花满院飘香雪，高楼夜静风筝咽。","斜月照帘帷，忆君和梦稀。","小窗灯影背，燕语惊愁态。","屏掩断香飞，行云山外归。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-x-juan.json#record-10","tags":[]},{"id":"poem-cde4cca35a2e42aaaf37da1f","title":"四睡赞  其二","author":"释了惠","dynasty":"宋","verses":["无固无必，挨肩促膝。","人梦不祥，虎梦大吉。","世上有谁知，天台云羃羃。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-84fa2316-d73d-42ae-b5bc-edfd030bfdd3","tags":[]},{"id":"poem-cde6b952f3dfbe87546574ff","title":"答僧慧文  其二","author":"释晓荣","dynasty":"宋","verses":["一念周沙界，日用万般通。","湛然常寂灭，常展自家风。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-09bc842e-8f54-4cd4-80e7-e5d893ebb541","tags":[]},{"id":"poem-cdeec5aed25afc321946f612","title":"于飞乐·休休得也","author":"宇文元质","dynasty":"宋","verses":["休休得也，只消更、一朵荼蘼。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-915","tags":[]},{"id":"poem-cdfbf7ab2b269d384b91cf1f","title":"叙旧游寄栖白","author":"李洞","dynasty":"唐","verses":["老着重袍坐石房，竺经休讲白眉长。","省冲鼍没投江岛，曾看鱼飞倚海樯。","晓炙冻盂原日气，夜挑莲椀禁灯光。","吟诗五岭寻无可，倏忽如今四十霜。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-28d46479-8ac0-44cf-befa-8d8c7ac61307","tags":[]},{"id":"poem-ce1295b9f031013cfa6823cd","title":"□明","author":"韩偓","dynasty":"唐","verses":["迢迢恩义吹区分。","（《断肠诗集前集》卷五《秋日杂书二首》郑元佐注引。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-a7dc1990-b61e-4fdc-b558-1ba4f2263c4c","tags":[]},{"id":"poem-ce1fa6644b93efee97e95ba2","title":"一封书","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["(末)婿百拜岳父前：自离膝下已数年。","因奸相不见怜，改调潮阳路八千。","今喜升为吉安守，遣仆相迎到任间。","匆匆的奉寸笺，仗乞尊颜照不宣。","(外)我听此书呵，。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8295","tags":[]},{"id":"poem-ce2d4735dad7aba70b8602c0","title":"南歌子·转盼如波眼","author":"温庭筠","dynasty":"唐","verses":["转盼如波眼，娉婷似柳腰。","花里暗相招，忆君肠欲断，恨春宵。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-1-juan.json#record-42","tags":[]},{"id":"poem-ce3aab8d64a8ff95a8b150c0","title":"河传·锦浦","author":"韦庄","dynasty":"五代","verses":["锦浦，春女，绣衣金缕。","雾薄云轻，花深柳暗，时节正是清明，雨初晴。","玉鞭魂断烟霞路，莺莺语，一望巫山雨。","香尘隐映，遥见翠槛红楼，黛眉愁。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-3-juan.json#record-6","tags":[]},{"id":"poem-ce3ad4a1252ce6cadcb9a9ff","title":"浣溪沙·密约深期卒未成","author":"方千里","dynasty":"宋","verses":["密约深期卒未成。","藏钩春酒坐频倾。","向人娇艳夜亭亭。","相顾无言情易觉，归来单枕梦犹惊。","眼梢怨泪几时晴。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-520","tags":[]},{"id":"poem-ce3b48e546f3bc21f469d816","title":"夜合花·柳锁莺魂","author":"史达祖","dynasty":"宋","verses":["柳锁莺魂，花翻蝶梦，自知愁染潘郎。","轻衫未揽，犹将泪点偷藏。","念前事，怯流光。","早春窥、酥雨池塘。","向销凝里，梅开半面，情满徐妆。","风丝一寸柔肠。","曾在歌边惹恨，烛底萦香。","芳机瑞锦，如何未织鸳鸯。","人扶醉，月依墙。","是当初、谁敢疏狂。","把闲言语，花房夜久，各自思量。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-183","tags":["宋词三百首"]},{"id":"poem-ce3b6537100b4664d86a4dbf","title":"将赴吴兴登乐游原一绝","author":"杜牧","dynasty":"唐","verses":["清时有味是无能，闲爱孤云静爱僧。","欲把一麾江海去，乐游原上望昭陵。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-24ca9268-9cbd-423b-b423-12e1a9aa9041","tags":["唐诗三百首","七言绝句","爱国"]},{"id":"poem-ce450a4ee4b7683da67b8cc1","title":"天仙子·金似衣裳玉似身","author":"韦庄","dynasty":"五代","verses":["金似衣裳玉似身，眼如秋水鬓如云，霞裙月帔一群群。","来洞口，望烟分，刘阮不归春日曛。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-3-juan.json#record-11","tags":[]},{"id":"poem-ce4767304af727b8092765f8","title":"冬景","author":"苏轼","dynasty":"宋","verses":["荷尽已无擎雨盖，菊残犹有傲霜枝。","一年好景君须记，最是橙黄橘绿时。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-冬景","tags":[]},{"id":"poem-ce4bfe4d6104a917c71f7856","title":"代人乞花","author":"李益","dynasty":"唐","verses":["绣户朝眠起，开帘满地花。","春风解人意，欲落妾西家。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-e25d24b0-a03f-4e3e-943c-8ca4ce2d917e","tags":[]},{"id":"poem-ce4ed9ecdce4b00bdb229b1c","title":"蝶恋花·水鉴中看尤未老","author":"黄裳","dynasty":"宋","verses":["水鉴中看尤未老。","乘兴拿舟，更向湘江过。","俯仰太虚都一个。","九春风思谁吟到。","闲上钓台云外坐。","待得金鳞，始放芳尊倒。","醉后言归犹更早。","素纤有数君须道。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-611","tags":[]},{"id":"poem-ce5145f268efda319910ae57","title":"从军行五首 二","author":"皎然","dynasty":"唐","verses":["韩斾拂丹霄，汉军新破辽。","红尘驱卤簿，白羽拥嫖姚。","战苦军犹乐，功高将不骄。","至今丁零塞，朔吹空萧萧。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-9a5d1655-e201-4e9e-ac7a-ae583c563707","tags":[]},{"id":"poem-ce5811972eae2cd4d0e56ee9","title":"颂古三十一首  其五","author":"释原妙","dynasty":"宋","verses":["攒花簇锦绝纤尘，一度拈来一度新。","啼得血流无用处，不如缄口过残春。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-e39f8f2f-2d97-449e-8919-2dbb4fc570e8","tags":[]},{"id":"poem-ce696ea4359a07ef6e77c054","title":"好事近·凝碧旧池头","author":"韩元吉","dynasty":"宋","verses":["凝碧旧池头，一听管弦凄切。","多少梨园声在，总不堪华发。","杏花无处避春愁，也傍野烟发。","惟有御沟声断，似知人呜咽。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-57","tags":["宋词三百首"]},{"id":"poem-ce70c87f9b7e28f32bebd6fc","title":"谢程帅袁制使  其一","author":"陈造","dynasty":"宋","verses":["昔人道与俱，物外一不假。","而我同是见，兼取及土苴。","虚心超万境，诗笔时一把。","造诣岂二机，此秘知者寡。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-a99ea8fc-3b9c-42d5-aa1a-96a879526d86","tags":[]},{"id":"poem-ce731cbc1d2a7ae0054e675c","title":"偈颂十二首  其一二","author":"释安永","dynasty":"宋","verses":["少处减些多处添，白云官路贩私盐。","一条性命俱抛下，不怕当初王令严。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-d6d6067a-6517-4578-9657-cb87ef99d2a9","tags":[]},{"id":"poem-ce79c5207f8d294da98896a2","title":"集宿姚殿中宅期僧无可不至","author":"马戴","dynasty":"唐","verses":["殿中日相命，开尊话旧时。","余钟催鸟绝，积雪阻僧期。","林静寒光远，天阴曙色迟。","今夕复何夕，人谒去难追。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-a62f2092-d6e9-4a7e-97a4-0baa12311aea","tags":[]},{"id":"poem-ce7efb100d7c7a00436b57cb","title":"题邸间壁","author":"郑会","dynasty":"宋","verses":["酴醿香梦怯春寒，翠掩重门燕子闲。","敲断玉钗红烛冷，计程应说到常山。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-題邸間壁","tags":[]},{"id":"poem-ce8293452bb1617ab0b16b0b","title":"渔家傲·四月芳林何悄悄","author":"欧阳修","dynasty":"宋","verses":["四月芳林何悄悄。","绿阴满地青梅小。","南陌采桑何窈窕。","争语笑。","乱丝满腹吴蚕老。","宿酒半醒新睡觉。","雏莺相语匆匆晓。","惹得此情萦寸抱。","休临眺。","楼头一望皆芳草。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-710","tags":[]},{"id":"poem-cea4f5df9c28f9017828d990","title":"自去冬不雨至今道傍井竭田多不耕有感","author":"李纲","dynasty":"宋","verses":["匝地风雷空震荡，终宵云雨竟虚无。","媮闲农具田皆废，暍死行人井半枯。","东海愆阳缘孝妇，桑林谒祷本谗夫。","忠魂昭雪奸邪逐，坐见为霖万物苏。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-7f315298-7352-4774-9051-3f55f354aa02","tags":[]},{"id":"poem-cea5053e220d938f2b6a7054","title":"吴楚歌词","author":"张籍","dynasty":"唐","verses":["庭前春鸟啄林声，红夹罗襦缝未成。","今朝社日停针线，起向朱樱树下行。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-4ddfd5e0-60cd-4227-b9fe-fc44ebf1bbde","tags":[]},{"id":"poem-cea5a1a924b19ee7d2b277f7","title":"忆多娇","author":"萧德祥《小孙屠》","dynasty":"元","verses":["心痛悲，珠泪暗滴。","不知我娘为下鬼，儿在囚牢谁看觑？(和)祸不单行，苦也娘亲怎知？(末)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8662","tags":[]},{"id":"poem-cea64f4148734de28fa44efa","title":"道延平适风雨雷电大作土人谓之剑归有感","author":"李纲","dynasty":"宋","verses":["干将未发埋酆城，光气上腾干列星。","张雷博识各有得，神物终合归延平。","没人下视不可取，天矫已作虬龙形。","至今千载有肸蚃，往往出入驱雷霆。","我来弭櫂双溪上，正昼云雾忽晦暝。","金蛇掣电起潭底，霹雳洊作声轰轰。","土人谓是剑归候，连日风雨资芽萌。","嗟嗟尔剑诚有灵，胡不奋飞辅助讨不庭。","群凶塞路盗贼横，夷狄外侮方骄狞。","佩之其人得所托，蠧国害民奸腰佞领逦迤皆削平。","何为终日但长啸，时出光怪惊动无知氓。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-e926364f-2913-4534-a2e4-d93bb2952abd","tags":[]},{"id":"poem-cea86dc0129033371d333aaa","title":"登金陵凤凰台","author":"李白","dynasty":"唐","verses":["凤凰台上凤凰游，凤去台空江自流。","吴宫花草埋幽径，晋代衣冠成古丘。","三山半落青天外，二水中分白鹭洲。","总为浮云能蔽日，长安不见使人愁。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-4af86c76-18b3-4069-be90-6d8cef430bc7","tags":["唐诗三百首","隋・唐・五代","七言律诗","一年级下册","高中古诗","咏史怀古"]},{"id":"poem-ceaf33cc451572e179e625ea","title":"书扇二首  其二","author":"赵文","dynasty":"宋","verses":["墙外数茎新竹，楼西一抹斜阳。","偶游蚁穴初觉，细听蝉声自凉。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-0fa440e3-f81b-4e79-b5c0-2bd24c553383","tags":[]},{"id":"poem-cec7a4457608a1fd2394e111","title":"天禧寺竹","author":"苏颂","dynasty":"宋","verses":["万个碧琅玕，两傍荫潭沼。","丛深蔽岩麓，干直露云表。","刹影下交加，山房上环绕。","昔尝止鸣凤，今肯栖凡鸟。","笋抽龙种瘦，箨坠孙枝小。","美胜会稽箭，珍逾汶阳筿。","兔园名非奇，渭川比终少。","樵删草根变，客玩茶烟燎。","创亭僧意高，谕佛禅心了。","吾爱有霜筠，一到忘昏晓。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-e1917355-e157-44a4-8cc1-b6b2e2886230","tags":[]},{"id":"poem-cececf4f85db4f578f3af647","title":"箬溪楼制锦堂长兴长官赵可斋新制  其二","author":"释居简","dynasty":"宋","verses":["古制宜藏巧，吾宁十目窥。","弗将青镜掩，谁兆白鸥疑。","雁鹜方群散，罝罦各自施。","悠然机杼别，无媿召南思。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-5aa56b9b-8904-4a0d-b5df-6cb50fb78c93","tags":[]},{"id":"poem-ced75fd1eff332a9ff3102d6","title":"七谏·谬谏","author":"东方朔","dynasty":"汉","verses":["怨灵修之浩荡兮，夫何执操之不固？","悲太山之为隍兮，孰江河之可涸？","愿承闲而效志兮，恐犯忌而干讳。","卒抚情以寂寞兮，然怊怅而自悲。","玉与石其同匮兮，贯鱼眼与珠玑。","驽骏杂而不分兮，服罢牛而骖骥。","年滔滔而自远兮，寿冉冉而愈衰。","心悇憛而烦冤兮，蹇超摇而无冀。","固时俗之工巧兮，灭规矩而改错。","郤骐骥而不乘兮，策驽骀而取路。","当世岂无骐骥兮，诚无王良之善驭。","见执辔者非其人兮，故驹跳而远去。","不量凿而正枘兮，恐矩矱之不同。","不论世而高举兮，恐操行之不调。","弧弓弛而不张兮，孰云知其所至？","无倾危之患难兮，焉知贤士之所死？","俗推佞而进富兮，节行张而不著。","贤良蔽而不群兮，朋曹比而党誉。","邪说饰而多曲兮，正法弧而不公。","直士隐而避匿兮，谗谀登乎明堂。","弃彭咸之娱乐兮，灭巧倕之绳墨。","菎蕗杂于黀蒸兮，机蓬矢以射革。","驾蹇驴而无策兮，又何路之能极？","以直针而为钓兮，又何鱼之能得？","伯牙之绝弦兮，无锺子期而听之。","和抱璞而泣血兮，安得良工而剖之？","同音者相和兮，同类者相似。","飞鸟号其群兮，鹿鸣求其友。","故叩宫而宫应兮，弹角而角动。","虎啸而谷风至兮，龙举而景云往。","音声之相和兮，言物类之相感也。","夫方圜之异形兮，势不可以相错。","列子隐身而穷处兮，世莫可以寄讬。","众鸟皆有行列兮，凤独翔翔而无所薄。","经浊世而不得志兮，愿侧身岩穴而自讬。","欲阖口而无言兮，尝被君之厚德。","独便悁而怀毒兮，愁郁郁之焉极？","念三年之积思兮，愿壹见而陈辞。","不及君而骋说兮，世孰可为明之？","身寝疾而日愁兮，情沉抑而不扬。","众人莫可与论道兮，悲精神之不通。","乱曰：鸾皇孔凤日以远兮，畜凫驾鹅。","鸡鹜满堂坛兮，鼍黾游乎华池。","要褭奔亡兮，腾驾橐驼。","铅刀进御兮，遥弃太阿。","拔搴玄芝兮，列树芋荷。","橘柚萎枯兮，苦李旖旎。","甂瓯登于明堂兮，周鼎潜潜乎深渊。","自古而固然兮，吾又何怨乎今之人。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-36","tags":[]},{"id":"poem-cedb72eca4a7793c3203383e","title":"勗劒","author":"曹唐","dynasty":"唐","verses":["古物神光雪见羞，未能擎出恐泉流。","暗临黑水蛟螭泣，潜倚空山鬼魅愁。","生怕雷霆号涧底，长闻风雨在床头。","垂情不用将闲气，恼乱司空犯斗牛。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-cc1f27bd-d0da-43d9-adb3-c33c9c9b02c7","tags":[]},{"id":"poem-cee1d2fd219b84c61d1018d6","title":"萧史图歌","author":"鲍溶","dynasty":"唐","verses":["霜绡数幅八月天，彩龙引凤堂堂然。","小载萧僊穆公女，随仙上归玉京去。","仙路迢遥烟几重，女衣清净云三素。","胡髯毵珊云髻光，翠蕤皎洁琼华凉。","露痕烟迹渍红貌，疑别秦宫初断肠。","此天每在西北上，紫霄洞客晓烟望。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-3e919f17-21ed-4f00-b331-78d9e2f39f36","tags":[]},{"id":"poem-cee70d19b0639e6a3aefa31a","title":"塞下曲四首 一","author":"王昌龄","dynasty":"唐","verses":["蝉鸣空桑林，八月萧关道。","出塞入塞寒，处处黄芦草。","从来幽幷客，皆共尘沙老。","莫学游侠儿，矜夸紫骝好。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-8d58a158-1a9b-4085-8ef7-b7b4e6adb66d","tags":["唐诗三百首","写景","游侠","乐府","讽刺","边塞","新乐府辞"]},{"id":"poem-ceec74387a4d1caa8bac4a91","title":"暮秋寄仙洲舍弟","author":"王镃","dynasty":"宋","verses":["去年泛菊醉重阳，今日谁知各异乡。","落叶石阑霜信早，败荷池屋雨声凉。","人情好恶花甘苦，世事荣枯草短长。","别有骏雕双翮健，刚风摩透入苍茫。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-e2bb58fe-737a-4c79-9899-ace1eba62c48","tags":[]},{"id":"poem-cefc1ecd1aadf597f5468cdf","title":"·","author":"轩辕伟","dynasty":"唐","verses":["。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-1ad24b75-635d-4538-8a15-1b3e5a2ed0ff","tags":[]},{"id":"poem-cf019344bde70ef49d70d7d0","title":"江行无题一百首 九十八","author":"钱珝","dynasty":"唐","verses":["万木已清霜，江边村事忙。","故溪黄稻熟，一夜梦中香。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-c2bb01ed-11bf-4919-8c6d-15f019e79e17","tags":[]},{"id":"poem-cf0219ede1136317567e9712","title":"伤清江上人","author":"刘言史","dynasty":"唐","verses":["往年偏共仰师游，闻过流沙泪不休。","此身岂得多时住，更著尘心起外愁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-b9e48b05-aa39-47f8-a9d8-06c15fd385f1","tags":[]},{"id":"poem-cf094755f3fb470c4191bb46","title":"游长宁公主流杯池二十五首 十七","author":"上官昭容","dynasty":"唐","verses":["岩壑恣登临，莹目复怡心。","风篁类长笛，流水当鸣琴。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-42f7d5fe-12aa-4b61-bc09-5a53316f474f","tags":[]},{"id":"poem-cf2814e1ebee0c983e29a4cb","title":"舜城怀古","author":"项斯","dynasty":"唐","verses":["禅禹逊尧聪，巍巍盛此中。","四隅咸启圣，万古赖成功。","道德去弥远，山河势不穷。","停车一再拜，帝业即今同。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-4f2af79e-69f3-4aa9-8857-9f25d75d8517","tags":[]},{"id":"poem-cf294f62d1f4d2accaf89a32","title":"伯兄新楼十首  其四","author":"王柏","dynasty":"宋","verses":["野色晴晖展画屏，绿槐古樾两娉婷。","却嫌一带无情竹，只放金华半段青。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-78ae8b19-806b-450b-ae53-b7e09c17746b","tags":[]},{"id":"poem-cf2993f2ef3aa76567fbfe49","title":"满庭芳·闽岭先春","author":"陈师道","dynasty":"宋","verses":["闽岭先春，琅函联璧，帝所分落人间。","绮窗纤手，一缕破双团。","云里游龙舞凤，香雾起、飞月轮边。","华堂静，松风竹雪，金鼎沸湲潺。","门阑。","车马动，扶黄籍白，小袖高鬟。","渐胸里轮囷，肺腑生寒。","唤起谪仙醉倒，翻湖海、倾泻涛澜。","笙歌散，风帘月幕，禅榻鬓丝斑。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-307","tags":[]},{"id":"poem-cf3942750184a37f61ad3e31","title":"故丞相高平范公挽歌辞三首  其一","author":"綦崇礼","dynasty":"宋","verses":["遇主方英妙，当朝独老成。","小车何耄耋，前席起公卿。","感会真千载，哀荣止半生。","伤心埋玉处，愁雾锁佳城。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-ab7d7478-1987-4e73-8500-94de5f026757","tags":[]},{"id":"poem-cf3d57d418476e86d867c588","title":"次韵钟汝楫","author":"陈造","dynasty":"宋","verses":["钟郎耐暑如被酒，亦复不闲读书口。","胸中莫可渚涯窥，笔下时作蛟龙吼。","老夫瞠若终后尘，儿子徒劳汗流走。","中年眼见花，养疴肘生柳。","漂然振我衰懦气，此士此诗今仅有。","亦思琢句与周旋，强敌当前难措手。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-0f7da0f5-43a5-4f06-b44c-453a9045d4fd","tags":[]},{"id":"poem-cf4000dc12d86682d171e00d","title":"俞义仲挽诗","author":"曾协","dynasty":"宋","verses":["适意平生水竹居，雌黄在手为藏书。","久看英子声名早，常恐良朋过往疎。","方喜安舆迎彩袖，忽惊平陌走丧车。","青松翠柏新阡路，常使行人泪满裾。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-6aebeb05-c9cd-4947-8e71-f640783a1eb5","tags":[]},{"id":"poem-cf44537f7af9a87c2ff0da7e","title":"对酒吟","author":"崔国辅","dynasty":"唐","verses":["行行日将夕，荒村古冢无人迹。","蒙笼荆棘一鸟吟，屡唱提壶沽酒吃。","古人不达酒不足，遗恨精灵传此曲。","寄言世上诸少年，平生且尽杯中醁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-0aad9c33-abf8-4236-8508-9907bf16abb9","tags":[]},{"id":"poem-cf45d130e9c5f0191db5e638","title":"柳堤 梅堤","author":"张栻","dynasty":"宋","verses":["亭亭堤上梅，历历波间影。","岁晚忆夫君，寂寞烟渚静。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-0af9c54e-23f6-4f53-8474-8808e0e3ca14","tags":[]},{"id":"poem-cf49b57aae07b9501e02681d","title":"和谢舍人雪夜寓直","author":"皇甫曾","dynasty":"唐","verses":["禁省夜沈沈，春风雪满林。","沧洲归客梦，青琐近臣心。","挥翰宣鸣玉，承恩在赐金。","建章寒漏起，更助掖垣深。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-9149aa7c-b352-4a0f-aaeb-85ab10403744","tags":[]},{"id":"poem-cf50b2093749412126bf5e86","title":"与诸子登岘山","author":"孟浩然","dynasty":"唐","verses":["人事有代谢，往来成古今。","江山留胜迹，我辈复登临。","水落鱼梁浅，天寒梦泽深。","羊公碑字在，读罢泪沾襟。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-b71d7c9c-7e92-4797-b2c9-8715dd0c2881","tags":["唐诗三百首","吊古伤今","隋・唐・五代","五言律诗"]},{"id":"poem-cf52c5fcb7e8b129578e4408","title":"题伏龙寺壁","author":"张栻","dynasty":"宋","verses":["少日忆曾到，归途得小留。","回还山寺古，萧瑟柿林秋。","道路情无那，琴书可细求。","从来士穷达，分付水悠悠。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-73792510-d749-402a-98a6-82af418e0320","tags":[]},{"id":"poem-cf6125156530113c3c2c6901","title":"潘司马别业","author":"周瑀","dynasty":"唐","verses":["门对青山近，汀牵绿草长。","寒深包晚橘，风紧落垂杨。","湖畔闻渔唱，天边数鴈行。","萧然有高士，清思满书堂。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-9eed79f1-49ed-4848-8df8-7f77613f00b4","tags":[]},{"id":"poem-cf6d5c4318689298c22bd116","title":"崇阳道中作四首  其三","author":"李纲","dynasty":"宋","verses":["承平无事久，万里尽农桑。","谁使干戈起，坐令民物疮。","关河成阻绝，京洛亦凄凉。","尚喜江湖外，斯民游乐康。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-d09d6ec9-971b-4359-a19f-2e53924cc4c8","tags":[]},{"id":"poem-cf6de499c647626bdd26889f","title":"更漏子 其三","author":"温庭筠","dynasty":"唐","verses":["金雀钗，红粉面，花里暂时相见。","如我意，感君怜，此情须问天。","香作穗，蜡成泪，还似两人心意。","山枕腻，锦衾寒，觉来更漏残。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-1-juan.json#record-16","tags":[]},{"id":"poem-cf7b41d0838dbd8094f5b1be","title":"永明山居诗（六十九首） 五十九","author":"延寿","dynasty":"唐","verses":["世途从此免相关，万虑潜消野思闲。","庵树逼春花自吐，岩巢欲暮鸟空还。","门前雾闭疑无路，槛外云开忽有山。","宴坐石岩樵径绝，姓名应不到人间。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-466773dc-154e-4eb8-896e-f486bfe06cd6","tags":[]},{"id":"poem-cf7bc4825bfa19300e521292","title":"虞美人·一轮丹桂窅窊树","author":"葛胜仲","dynasty":"宋","verses":["一轮丹桂窅窊树。","光景疑非暮。","天公著意在兹时。","扫尽微云点缀、展清池。","樽前金奏无晨露。","只有君房语。","骊驹客莫赋归诗。","东道留连应赋、不庸归。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-10","tags":[]},{"id":"poem-cf805d7057671d7ee15e1698","title":"歌者十二首 四","author":"司空图","dynasty":"唐","verses":["不似新声唱亦新，旋调玉管旋生春。","愁肠隔断珠帘外，只为今宵共听人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-9ba6ab81-6c19-470d-8947-d0494dc77810","tags":[]},{"id":"poem-cf81fc416dd2a52dcd09de32","title":"新楼诗二十首 望海亭","author":"李绅","dynasty":"唐","verses":["乌盈兔缺天涯迥，鹤背松梢拂槛低。","湖镜坐隅看匣满，海涛生处辨云齐。","夕岚明灭江帆小，烟树苍茫客思迷。","萧索感心俱是梦，九天应共草萋萋。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-66ca7165-e0a8-4532-93f9-b2835385daae","tags":[]},{"id":"poem-cf86c39f2243cb9f31293af6","title":"中秋月","author":"杜牧","dynasty":"唐","verses":["暮云收尽溢清寒，银汉无声转玉盘。","此生此夜不长好，明月明年何处看？"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-中秋月","tags":[]},{"id":"poem-cf902abd3d0f32517fe410d7","title":"游包道士山居","author":"李纲","dynasty":"宋","verses":["何日养铅丹，幽居紫翠间。","架岩开户牖，隐几俯溪山。","昔到浑如梦，今游更觉闲。","兵戈知满地，佳处且跻攀。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-4a22f971-1732-4f3d-9a7e-68a21c9fa092","tags":[]},{"id":"poem-cf96492413208c9ed185aa9a","title":"南乡子·天外雨初收","author":"蔡伸","dynasty":"宋","verses":["天外雨初收。","风紧云轻已变秋。","邂逅故人同一笑，迟留。","聚散人生宜自谋。","去路指南州。","万顷云涛一叶舟。","莫话太湖波浪险，归休。","人在溪边正倚楼。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-974","tags":["太湖"]},{"id":"poem-cf994c0a28b84574b9750bba","title":"人日侍䜩大明宫应制","author":"赵彦昭","dynasty":"唐","verses":["宝契无为属圣人，雕舆出幸玩芳辰。","平楼半入南山雾，飞合旁临东墅春。","夹路秾花千树发，垂轩弱柳万条新。","处处风光今日好，年年愿奉属车尘。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-6f3e2276-e5f0-48e4-946e-c0febd9b9e0c","tags":[]},{"id":"poem-cf9b3e9fb25abaeff1b97bde","title":"菩萨蛮·忆郎还上层楼曲","author":"张先","dynasty":"宋","verses":["忆郎还上层楼曲。","楼前芳草年年绿。","绿似去时袍。","回头风袖飘。","郎袍应已旧。","颜色非长久。","惜恐镜中春。","不如花草新。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-266","tags":[]},{"id":"poem-cf9ee53a18792f767b9a7db2","title":"兵要望江南 禳厌第二十四（京本作「占厌禳第十九」○十三首） 十三","author":"易静","dynasty":"唐","verses":["扬兵吉（京本作「禳兵告」），顿在（辛本、川本、京本作「须向」）九天方。","诸恶不成加喜气。","更宜上将见恩光，安得（京本作「将」）有乖张。","（《太乙式》云：「九天之上，可以陈兵，九地之下，可以潜伏。","」）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-529d7a1e-91e6-4c71-aad9-6f174b976c4b","tags":[]},{"id":"poem-cf9f117643e2a8720654fa4f","title":"蝶恋花·巧语娇莺春未暮","author":"吕本中","dynasty":"宋","verses":["巧语娇莺春未暮。","杨柳风流，恰过池塘雨。","芳草满庭花满树。","无情胡蝶飞来去。","睡起小奁香一缕。","玉篆回纹，等个人分付。","桃叶不言人不语。","眉尖一点君知否。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-751","tags":[]},{"id":"poem-cfa3e47cf78da67492286958","title":"小游仙诗九十八首 三十八","author":"曹唐","dynasty":"唐","verses":["忘却教人锁后宫，还丹失尽玉壶空。","嫦娥若不偷灵药，争得长生在月中。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-d2d5f2f0-c40e-4c0b-8e3c-f02ab9840812","tags":[]},{"id":"poem-cfaf34c5f69c4f05a045acc9","title":"寄沙阳邓季明二首  其一","author":"李纲","dynasty":"宋","verses":["海上归来近七峰，故人犹冀一樽同。","心忧世故存当日，身履时危到此中。","玉带金鱼非素志，碧斋翠阁自清风。","十年扰扰成何事，依旧梁谿一拙翁。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-a0776a04-cd27-45c3-838e-77e5a18b8f20","tags":[]},{"id":"poem-cfafeeaddd4aca396be51d84","title":"头陀寺看竹","author":"李涉","dynasty":"唐","verses":["寺前新笋已成竿，策马重来独自看。","可惜班皮空满地，无人解取作头冠。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-1bd22d03-97d2-4f6f-8f08-11fe9302c109","tags":[]},{"id":"poem-cfb0a582f41fb63a98a402cf","title":"念奴娇·霁天湛碧","author":"谢懋","dynasty":"宋","verses":["霁天湛碧。","正新凉风露，冰壶清彻。","河汉无声光练练，涌处银蟾孤绝。","岩桂香飘，井梧影转，冷浸官袍洁。","西厢往事，一帘清梦凄切。","肠断楚峡云归，尊前无绪，知有愁如发。","此夕常娥应也恨，冷落琼楼金阕。","禁漏迢迢，边鸿杳杳，幽意凭谁决。","阑干星斗，落梅三弄初阕。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-299","tags":[]},{"id":"poem-cfb1e244e76bf838fec443a1","title":"旧同官张法曹","author":"宋伯仁","dynasty":"宋","verses":["熬波同看楚天秋，多少艰难说未休。","今日共依湖柳住，梦中犹怕踏边头。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-e92aa381-9ca8-4bc2-a505-52c06b492cd1","tags":[]},{"id":"poem-cfba330d5fb2b3ec45788474","title":"烛影摇红/望江南/烛影摇红","author":"无名氏《张协状元》","dynasty":"元","verses":["(生)暂籍轧色。","(众)有。","(生)罢！学个张状元似像。","(众)谢了！(生)画堂悄最堪宴乐，绣帘垂隔断春风。","波艳艳杯行泛绿，夜深深烛影摇戏。","(众应)(生唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2454","tags":[]},{"id":"poem-cfbdd7847a2aced129380c9f","title":"解连环·楚江空晚","author":"张炎","dynasty":"宋","verses":["楚江空晚。","怅离群万里，恍然惊散。","自顾影、欲下寒塘，正沙净草枯，水平天远。","写不成书，只寄得、相思一点。","料因循误了，残毡拥雪，故人心眼。","谁怜旅愁荏苒。","谩长门夜悄，锦筝弹怨。","想伴侣、犹宿芦花，也曾念春前，去程应转。","暮雨相呼，怕蓦地、玉关重见。","未羞他、双燕归来，画帘半卷。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-260","tags":["宋词三百首"]},{"id":"poem-cfbedf0e3b9a370c0f670122","title":"兵要望江南 《周易》占候第二十六（三十七首） 二十五","author":"易静","dynasty":"唐","verses":["世若墓，我军且默（辛本、川本作「执」）屯。","应爻被尅休囚位，来军必败损人兵，我众喜忻忻。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-58540232-e9b2-42bf-b475-5fe123ca2ab4","tags":[]},{"id":"poem-cfdef4dae73ba26f596ca4f0","title":"鴈来红","author":"释居简","dynasty":"宋","verses":["夜夜灯花巧胜裁，家书准拟傍秋开。","鴈来红叶都红了，目断西风鴈不来。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-7b67156f-da01-425b-919a-eaf3239f2cc4","tags":[]},{"id":"poem-cfe006a00a13137999094d66","title":"盛山十二诗 流桮渠","author":"韦处厚","dynasty":"唐","verses":["激曲萦飞箭，浮沟泛满巵。","将来山太守，早向习家池。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-2a8f42ef-af07-4b36-b905-fada91ba6808","tags":[]},{"id":"poem-cfe7e4e139cda537501e697b","title":"酒泉子·黛薄红深","author":"顾敻","dynasty":"五代","verses":["黛薄红深，约掠绿鬟云腻。","小鸳鸯，金翡翠，称人心。","锦鳞无处传幽意，海燕兰堂春又去。","隔年书，千点泪，恨难任。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-7-juan.json#record-11","tags":[]},{"id":"poem-d000fede452fcec1ac7568ed","title":"天仙子·蟾彩霜华夜不分","author":"韦庄","dynasty":"五代","verses":["蟾彩霜华夜不分，天外鸿声枕上闻，绣衾香冷懒重熏。","人寂寂，叶纷纷，才睡依前梦见君。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-3-juan.json#record-9","tags":[]},{"id":"poem-d0038fa5c94ff2e6e567a05f","title":"颂古三十一首  其六","author":"释玿","dynasty":"宋","verses":["大雄山下老狐精，千古丛林恼杀人。","若遇金毛师子子，看伊无处著浑身。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-533060c4-d84e-43c5-bee2-dcf7771f9922","tags":[]},{"id":"poem-d00f54c564f6e9da7e8f047b","title":"十无诗寄桂府杨中丞 一","author":"赵嘏","dynasty":"唐","verses":["琴酒曾将风月须，谢公名迹满江湖。","不知贵拥旌旗后，犹暇怜诗爱酒无。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-55d37a59-81c0-4c02-adab-5ec0a29b67c4","tags":[]},{"id":"poem-d00f63c49f75c12051110c28","title":"永明山居诗（六十九首） 二十九","author":"延寿","dynasty":"唐","verses":["幽栖岂可事徒然，昼讽《莲经》夜坐禅。","吟里有声皆实相，定中无境不虚玄。","直教似月临千界，还遣如空度万缘。","从此必知宏此志，免教虚掷愧前贤。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-323bc192-d517-46b2-a626-3ec5ba001365","tags":[]},{"id":"poem-d01c4beeb58b0071aa3e9c2f","title":"题壁","author":"无名氏","dynasty":"","verses":["一团茅草乱蓬蓬，蓦地烧天蓦地空。","争似满炉煨榾柮，漫腾腾地暖烘烘。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-題壁","tags":[]},{"id":"poem-d024e492e5e3e2b09fb71a74","title":"奉和圣制送张说巡边","author":"王光庭","dynasty":"唐","verses":["贤相德符充，朝推文武雄。","海波先若镜，关草豫从风。","钺助将军勇，威成天子功。","琼章九霄发，锡宴五衢通。","玉辗龙盘带，金装凤勒骢。","虎貔纷儗儗，河洛振熊熊。","戈剑千霜白，旌旗万火红。","示刑夷夏变，流惠鬼方同。","寇息军容偃，尘销朔野空。","用师敷礼乐，非是为獯戎。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-e1b1a72d-b466-4bf3-bb80-8f3c6de9cc49","tags":[]},{"id":"poem-d02631dd52d38c6be6a5d975","title":"子夜歌·人生愁恨何能免","author":"李煜","dynasty":"五代","verses":["人生愁恨何能免，销魂独我情何限。","故国梦重归，觉来双泪垂。","高楼谁与上？长记秋晴望。","往事已成空，还如一梦中。"],"enabled":true,"collection":"南唐二主词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/nantang/poetrys.json#record-7","tags":[]},{"id":"poem-d0390871a06c92d96ca88774","title":"西江月·竹寺青灯永夜","author":"向","dynasty":"宋","verses":["竹寺青灯永夜，江城黄叶高秋。","当时文物尽交游。","更为笛声怀旧。","牢落一生羁思，风流万斛诗愁。","强邀从事到青州。","酒病绵绵越瘦。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-195","tags":[]},{"id":"poem-d043b2e156f40f75e7f0c171","title":"浣溪沙·晚出闲庭看海棠","author":"李珣","dynasty":"五代","verses":["晚出闲庭看海棠，风流学得内家妆，小钗横戴一枝芳。","镂玉梳斜云鬓腻，缕金衣透雪肌香，暗思何事立残阳。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-x-juan.json#record-14","tags":[]},{"id":"poem-d04785d6a10af12ef0831616","title":"次张文昌送川张道人韵","author":"释居简","dynasty":"宋","verses":["万水遶千山，翩然去不难。","双明元自碧，方寸为谁丹。","鹤化曾留句，凫轻欲振翰。","不知藏世界，一粟几何宽。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-0b51651a-a8d3-414a-8a3e-ce8ed9d79d02","tags":[]},{"id":"poem-d04f6ce6468ea83dcd2e56eb","title":"和子骏约游一二园亭看花遇雨而止","author":"司马光","dynasty":"宋","verses":["行乐及佳时，官闲无所覉。","只知花正发，不共雨为期。","浅草碧无际，浓云冷四垂。","陪游兴未尽，安得不相思。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-cff1eb52-0c9f-4e96-be22-de307a8e59be","tags":[]},{"id":"poem-d05144492ce6a5f62e545acd","title":"玉楼春·绿杨芳草长亭路","author":"晏殊","dynasty":"宋","verses":["绿杨芳草长亭路。","年少抛人容易去。","楼头残梦五更钟，花底离情三月雨。","无情不似多情苦。","一寸还成千万缕。","天涯地角有穷时，只有相思无尽处。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-167","tags":["宋词三百首"]},{"id":"poem-d059e817783f7ded8d186b6f","title":"宝鼎儿","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["小门深巷里，春到芳草，人闲清昼。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-4911","tags":[]},{"id":"poem-d06908cc0799577bfe94d379","title":"荷叶鱼儿","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["［外上］春雨新收，喜见山明水秀，万花深处有鸣鸠，软红泥踏青时候。","试蹑青鞋，慢拖斑竹，去寻良友。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8048","tags":[]},{"id":"poem-d06e5f5128907b3878c87ea2","title":"野岸白莲","author":"华镇","dynasty":"宋","verses":["越溪深处楚江湄，玉刻冰裁一两枝。","天借明蟾滋秀色，云垂清露润丰肌。","解知洁素风神远，始觉红鲜品格卑。","何日曲池亭槛上，细看朝暮弄轻飔。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-731bac62-d015-4a29-8515-656a8d244ead","tags":[]},{"id":"poem-d06f46817445e008d39f46fc","title":"庆春宫・高阳台·宿霭笼晴","author":"方千里","dynasty":"宋","verses":["宿霭笼晴。","层云遮日，送春望断愁城。","篱落堆花，帘栊飞絮，更堪远近莺声。","岁华流转，似行蚁、盘旋万星。","人生如寄，利锁名缰，何用萦萦。","骎骎皓发相迎。","斜照难留，朝雾多零。","宜趁良辰，何妨高会，为酬月皎风清。","舞台歌榭，遇得旅、欢期易成。","莫辞杯酒，天赋吾曹，特地锺情。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-538","tags":[]},{"id":"poem-d070b7c19e46800db80147f5","title":"关山曲二首 一","author":"马戴","dynasty":"唐","verses":["金甲耀兜鍪，黄金拂紫骝。","叛羌旗下戮，陷壁夜中收。","霜霰戎衣月，关河碛气秋。","箭疮殊未合，更遣击兰州。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-9ac46ba9-d263-4cc8-8ce3-d10e628ae8f7","tags":[]},{"id":"poem-d073567ecbedc62ba1e3076a","title":"陈情上李景让大夫","author":"刘得仁","dynasty":"唐","verses":["一被浮名误，旋遭白发侵。","裴回恋明主，梦寐在秋岑。","遇物唯多感，居常只是吟。","待时钳定口，经事压低心。","辛苦文场久，因缘戚里深。","老迷新道路，贫卖旧园林。","晴赏行闻水，宵棋坐见参。","龟留闲去问，僧约偶来寻。","望喜潜凭鹊，娱情愿有琴。","此生如遂意，誓死报知音。","上德怜孤直，唯公拔陆沈。","丘山恩忽被，蝼蚁力难任。","作鉴明同日，听言重若金。","从兹更无限，翘足俟为霖。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-b0681f1f-81d3-478f-98c2-39bbd6a5657a","tags":[]},{"id":"poem-d075fb8be5914ffc55a19393","title":"赠海东僧","author":"张籍","dynasty":"唐","verses":["别家行万里，自说过扶余。","学得中州语，能为外国书。","与医收海藻，持咒取龙鱼。","更问同来伴，天台几处居。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-fdeadecf-359a-4514-96e5-fe73d31997e1","tags":[]},{"id":"poem-d07a68c9ed74fb8422c78a1a","title":"和三乡诗","author":"张绮","dynasty":"唐","verses":["洛川依旧好风光，莲帐无因见女郎。","云雨散来音信断，此生遗恨寄三乡。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-36bdfe34-1016-4b81-98fe-865c009ace28","tags":[]},{"id":"poem-d07c104bfc1e0aea11c8262f","title":"柳枝·桥北桥南千万条","author":"牛峤","dynasty":"五代","verses":["桥北桥南千万条，恨伊张绪不相饶。","金羁白马临风望，认得杨家静婉腰。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-3-juan.json#record-47","tags":[]},{"id":"poem-d0800d00cc49392b46e1fa95","title":"上行杯·白马玉鞭金辔","author":"韦庄","dynasty":"五代","verses":["白马玉鞭金辔，少年郎，离别容易，迢递去程千万里。","惆怅异乡云水，满酌一杯劝和泪，须愧珍重意，莫辞醉。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-3-juan.json#record-19","tags":[]},{"id":"poem-d0830f927ff2068da044559a","title":"卜算子·要见不得见","author":"黄庭坚","dynasty":"宋","verses":["要见不得见，要近不得近。","试问得君多少怜，管不解、多于恨。","禁止不得泪，忍管不得闷。","天上人间有底愁，向个里、都谙尽。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-818","tags":[]},{"id":"poem-d08558dcd781f819368c4600","title":"惜花","author":"张佖","dynasty":"宋","verses":["蝶散鶑啼尚数枝，日斜风定更离披。","看多记得伤心事，金谷楼前委地时。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-a475850b-b959-4324-a1b9-0e9686399be1","tags":[]},{"id":"poem-d08b45d653e7b8d6fbf6fa52","title":"夏日金陵制幕即事  其二","author":"王同祖","dynasty":"宋","verses":["早来留得气清明，吏捧军书课日程。","秉烛搀先书押了，闲欹凉枕数残更。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-7f862b9e-3280-464a-bd22-3a8da397e260","tags":[]},{"id":"poem-d08ff5bfca776c3641beaf9d","title":"女曰鸡鸣","author":"佚名","dynasty":"先秦","verses":["女曰鸡鸣，士曰昧旦。子兴视夜，明星有烂。将翱将翔，弋凫与雁。","弋言加之，与子宜之。宜言饮酒，与子偕老。琴瑟在御，莫不静好。","知子之来之，杂佩以赠之。知子之顺之，杂佩以问之。知子之好之，杂佩以报之。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-81","tags":[]},{"id":"poem-d0944cc9b3fee81e2e41552b","title":"洞庭隐","author":"来鹄","dynasty":"唐","verses":["高卧洞庭三十春，芰荷香里独垂纶。","莫嫌无事闲销日，有事始怜无事人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-59cf3dc1-497f-48e1-b4f9-f6acb2b1978e","tags":["洞庭湖"]},{"id":"poem-d09b9cc97aa6ed38d1b29898","title":"题王处士山居","author":"刘得仁","dynasty":"唐","verses":["茅堂入谷远，林暗绝其邻。","终日有流水，经年无到人。","溪云常欲雨，山洞别开春。","自得仙家术，栽松独养真。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-7ec90e57-dc10-4b78-a5ee-522f9b0c781b","tags":[]},{"id":"poem-d09d8e934e385f9bb5dd488f","title":"送庞百篇之任青阳县尉","author":"张乔","dynasty":"唐","verses":["都堂公试日，词翰独超群。","品秩台庭与，篇章圣主闻。","乡连三楚树，县对九华云。","多少青门客，临岐共羡君。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-a341fedf-e08f-41a6-a65c-84853ad63ad5","tags":[]},{"id":"poem-d09ef9966a807592a9b16a25","title":"永明山居诗（六十九首） 二十六","author":"延寿","dynasty":"唐","verses":["雾锁烟霾宴寂堂，含虚凝绿水云乡。","搜玄偈里真风远，招隐诗中野思长。","真柏最宜堆厚雪。","危花终怯下轻霜。","滔滔一点无依处，举足方知尽道场。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-cfd2c548-ae3f-41d2-8d69-a542f30391ff","tags":[]},{"id":"poem-d0a40410e6fec90e98006b79","title":"和渊眀拟古九首  其四","author":"李纲","dynasty":"宋","verses":["弃置帝王宅，乃欲保一隅。","一隅岂易保，巨盗连荆舒。","眷言浙江西，有我先人庐。","兵火偶不到，聚族于焉居。","羁束未得归，田园日将芜。","江边畏群盗，岁暮当何如。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-bd9a6dfe-fc16-4a02-8672-617ea17884f0","tags":[]},{"id":"poem-d0a49f3fdb8e1432af53b818","title":"赠衡山令","author":"裴说","dynasty":"唐","verses":["君吟十二载，辛苦必能官。","造化犹难隐，生灵岂易谩。","猿跳高岳静，鱼摆大江宽。","与我为同道，相留夜话阑。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-76f9562f-aa08-4257-9634-c3e714326076","tags":["衡山"]},{"id":"poem-d0a5286fd21b272426c05a05","title":"钓台  其一","author":"艾可翁","dynasty":"宋","verses":["归去江头伸脚眠，不烦太史验星躔。","一丝千古经纶在，不为东都二百年。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-f5eb9c1e-24a5-4c88-b162-2777d466a77d","tags":[]},{"id":"poem-d0afa1e0c4b683b558ef7b62","title":"秋夕","author":"张乔","dynasty":"唐","verses":["春恨复秋悲，秋悲难到时。","每逢明月夜，长起故山思。","巷僻行吟远，蛩多独卧迟。","溪僧与樵客，动别十年期。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-3e22fdfe-3e2f-4130-a417-bb748a736edd","tags":[]},{"id":"poem-d0b00408ec183e8945fa7beb","title":"扈跸霸州","author":"纳兰性德","dynasty":"清","verses":["霸山重镇奠神京，鸾辂春游淑景明。","万呱银涛冲古岸，四围玉甃护严城。","花乘暖日迎来骑，柳带新膏绾去旌。","八寨雄图今更固，行随赏乐胜蓬瀛。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-224","tags":[]},{"id":"poem-d0b4d602d7fd056e13391352","title":"题粲姪岘山秋晚","author":"释居简","dynasty":"宋","verses":["分明写出岘山诗，陇树初寒晚照低。","掩卷只思人堕泪，不思量到白铜鞮。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-3aaeb2e8-d2e8-4242-bc5e-3a58fbbcc3f4","tags":[]},{"id":"poem-d0c09d8d99b546b615367d14","title":"送李秀才赴婺州招","author":"皎然","dynasty":"唐","verses":["山开江色上，孤赏去应迟。","绿水迎吴榜，秋风入楚词。","猨清独宿处，木落远行时。","见说东阳守，登楼为尔期。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-cd6dc609-00ed-4d26-9b1c-797f0d1c67d7","tags":[]},{"id":"poem-d0d95015193eda60325dae3a","title":"泊海子口","author":"陈造","dynasty":"宋","verses":["池口至海口，望望三舍外。","辰发莫已到，回首西日在。","风师肯怜客，祖道烦一嗌。","我舟疑凌虚，楚山真历块。","蜚鸟相让疾，惊浪乃弗逮。","穷涂坐局缩，颇尝得此快。","遄迈自本图，阙供恐贻悔。","未办问村胶，且计具薪菜。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-4945077e-15b3-4bc5-9120-9e3117f20b4d","tags":[]},{"id":"poem-d0db86ffb085fec4ec86f2da","title":"六丑·正单衣试酒","author":"周邦彦","dynasty":"宋","verses":["正单衣试酒，恨客里、光阴虚掷。","愿春暂留，春归如过翼。","一去无迹。","为问花何在，夜来风雨，葬楚宫倾国。","钗钿堕处遗香泽。","乱点桃蹊，轻翻柳陌。","多情为谁追惜。","但蜂媒蝶使，时叩窗隔。","东园岑寂。","渐蒙笼暗碧。","静绕珍丛底，成叹息。","长条故惹行客。","似牵衣待话，别情无极。","残英小、强簪巾帻。","终不似一朵，钗头颤袅，向人侧。","漂流处、莫趁潮汐。","恐断红、尚有相思字，何由见得。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-236","tags":["宋词三百首"]},{"id":"poem-d0f029cd5159ea53da24099a","title":"送陆侍御余庆北使","author":"沈佺期","dynasty":"唐","verses":["古人贵将命，之子出𬨎轩。","受委当不辱，随时敢赠言。","朔途际辽海，春思绕轘辕。","安得回白日，留欢尽绿樽。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-f16cd2b4-b395-432f-888b-27a1246fdb32","tags":[]},{"id":"poem-d0f503e61b6428e9af1f9015","title":"狂题十八首 九","author":"司空图","dynasty":"唐","verses":["地下修文著作郎，生前饥处倒空墙。","何如神爽骑星去，犹自研几助玉皇。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-6402c50c-a59c-4c76-aefb-f14e9be09d6b","tags":[]},{"id":"poem-d0f9afa61e6a3da3549ad1fa","title":"霜天晓角·重来丁酒","author":"纳兰性德","dynasty":"清","verses":["重来丁酒，折尽风前柳。","若问看花情绪，似当日，怎能够。","休为西风瘦，痛饮频搔首。","自古青蝇白璧，天已早安排就。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-206","tags":[]},{"id":"poem-d0ff5fba5a501ec8a15b53c3","title":"瑶瑟怨","author":"温庭筠","dynasty":"唐","verses":["冰簟银床梦不成，碧天如水夜云轻。","雁声远过潇湘去，十二楼中月自明。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-b7d50789-e0d5-4291-8014-eddf65a124df","tags":["唐诗三百首","离别","七言绝句","闺怨"]},{"id":"poem-d1055437c9977fc8edca8266","title":"梦江南·含泥燕","author":"牛峤","dynasty":"五代","verses":["含泥燕，飞到画堂前。","占得杏梁安稳处，休轻唯有主人怜，堪羡好因缘。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-4-juan.json#record-4","tags":[]},{"id":"poem-d1088bcc6f5d2ba9e03b1ab2","title":"谢秦王","author":"何仲举","dynasty":"唐","verses":["三千里外抛渔艇，二十人前折桂枝。","（见《增修诗话总龟》卷三六引《青琐集》）（〖1〗《青琐集》云：「王仲举，营道人，母尝梦挟仲举入月。","仲举修进业，长兴〖化〗二年赴举，谒秦王登第，后有诗谢秦王）（曰〖略〗。","太平兴国中，仲举有子曰嗣全，亦中进士第，乃挟两子入月之祥。","」以《五代史补》卷二载何仲举事迹参证，知「王仲举」为「何仲举」之误。","二书所载及第年有异，未详孰是。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-12150916-d0ab-4cdf-94b0-b90090324297","tags":[]},{"id":"poem-d1093e89d024aa9bf16f8a36","title":"葛无怀讣至  其二","author":"释居简","dynasty":"宋","verses":["静胜知天定，虚明悟物齐。","略伸嗟屈蠖，欲吐丧晴霓。","夜雨灯侵幌，春风柳竝堤。","漫天吹絮尽，一点不沾泥。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-3ce0caca-191c-44cb-86ff-22befa8d9d9e","tags":[]},{"id":"poem-d10a34a5a4b6b5fd6590578f","title":"八声甘州·对潇潇、暮雨洒江天","author":"柳永","dynasty":"宋","verses":["对潇潇、暮雨洒江天，一番洗清秋。","渐霜风凄惨，关河冷落，残照当楼。","是处红衰翠减，苒苒物华休。","惟有长江水，无语东流。","不忍登高临远，望故乡渺邈，归思难收。","叹年来踪迹，何事苦淹留。","想佳人、妆楼望，误几回、天际识归舟。","争知我、倚阑干处，正恁凝愁。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-151","tags":["宋词三百首","长江"]},{"id":"poem-d112d4a0f30f35bf88d7147a","title":"菩萨蛮·山亭水榭秋方半","author":"朱淑真","dynasty":"宋","verses":["山亭水榭秋方半。","凤帏寂寞无人伴。","愁闷一番新。","双蛾只旧颦。","起来临绣户。","时有疏萤度。","多谢月相怜。","今宵不忍圆。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-873","tags":[]},{"id":"poem-d115b02664af5074167659f6","title":"次韵陈中玉大卿二首  其二","author":"李纲","dynasty":"宋","verses":["叨尘黄阁值明时，推挽英髦愧力微。","海上相逢颜愈渥，箧中谁谓出无衣。","救焚拯溺非天数，修政攘夷赖主威。","旧国故乡休怅望，中兴恢复伫旋归。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-0629b767-1d6a-43c2-88e6-4c4e98c133fc","tags":[]},{"id":"poem-d125c563729a563f00e70f83","title":"浄名  其二","author":"米芾","dynasty":"宋","verses":["旧对湘西雪，迟迟忆故关。","水云资老景，吟引谢江山。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-b67b9d65-3d33-4600-8288-52817c5b826a","tags":[]},{"id":"poem-d133c6f7fe297b70b54e2388","title":"画堂春·东堂西畔有池塘","author":"黄庭坚","dynasty":"宋","verses":["东堂西畔有池塘。","使君棐几明窗。","日西人吏散东廊。","蒲苇送清凉。","翠管细通岩溜，小峰重叠山光。","近池催置琵琶床。","衣带水风香。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-702","tags":[]},{"id":"poem-d1368866db45369b8c8d61f3","title":"春日杂兴  其四","author":"王同祖","dynasty":"宋","verses":["百花时节燕莺忙，昼日如年懒课香。","午枕梦回人悄悄，一声啼鸟傍斜阳。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-b1ebc6c3-f357-46ec-ba25-39d7e2408a99","tags":[]}];
